(window.SLIDES = window.SLIDES || []).push(
  // ── Napoleon & Ende des HRR ──
  { id: "ge2-001", cat: "geschichte", topic: "Napoleon", type: "event", emoji: "👑", level: 2, year: "1806",
    title: "Das Heilige Römische Reich endet",
    text: "Am 6. August 1806 legt Kaiser Franz II. die Krone nieder. Kurz zuvor hatten sich 16 deutsche Fürsten unter Napoleons Schutz zum **Rheinbund** zusammengeschlossen und waren aus dem Reich ausgetreten.",
    more: "Das Reich bestand seit 962 (Otto I.) – rund 850 Jahre. Franz hatte sich schon 1804 vorsorglich zum Kaiser von Österreich gemacht (als Franz I.). Merkhilfe: 1806 = Ende des „alten Reichs“, 1871 = Gründung des neuen." },
  { id: "ge2-002", cat: "geschichte", topic: "Napoleon", type: "event", emoji: "🗺️", level: 3, year: "1803",
    title: "Reichsdeputationshauptschluss: Flurbereinigung der Landkarte",
    text: "Geistliche Fürstentümer werden enteignet (**Säkularisation**), kleine Herrschaften und Reichsstädte großen Nachbarn zugeschlagen (**Mediatisierung**). Aus Hunderten Territorien werden wenige Mittelstaaten.",
    more: "Gewinner waren vor allem Bayern, Württemberg und Baden – sie verdanken ihre heutige Größe im Kern Napoleon. Die Vereinfachung der Landkarte erleichterte später die nationale Einigung." },
  { id: "ge2-003", cat: "geschichte", topic: "Napoleon", type: "fact", emoji: "⚖️", level: 2,
    title: "Code civil (1804): Napoleons langlebigster Export",
    text: "Das französische Zivilgesetzbuch garantierte Gleichheit vor dem Gesetz, Eigentumsschutz, Vertragsfreiheit und die Zivilehe. Es galt auch in den von Frankreich beherrschten deutschen Gebieten.",
    more: "Im linksrheinischen Rheinland galt der Code civil bis zur Einführung des BGB am 1. Januar 1900. Napoleon selbst hielt ihn für wichtiger als alle Schlachten: „Mein wahrer Ruhm sind nicht die 40 gewonnenen Schlachten … was ewig leben wird, ist mein Code civil.“" },
  { id: "ge2-004", cat: "geschichte", topic: "Napoleon", type: "event", emoji: "⚔️", level: 1, year: "1813",
    title: "Völkerschlacht bei Leipzig",
    text: "Vom 16. bis 19. Oktober 1813 besiegen Preußen, Österreich, Russland und Schweden Napoleon. Mit rund 600.000 beteiligten Soldaten war es die größte Schlacht der Weltgeschichte bis zum Ersten Weltkrieg.",
    more: "Vorausgegangen war der gescheiterte Russlandfeldzug 1812, bei dem Napoleons „Grande Armée“ fast vollständig unterging. Das Völkerschlachtdenkmal wurde genau 100 Jahre später, 1913, eingeweiht." },
  { id: "ge2-005", cat: "geschichte", topic: "Napoleon", type: "quiz", emoji: "🏳️", level: 1,
    q: "Welche Schlacht beendete Napoleons Herrschaft endgültig?",
    options: ["Austerlitz", "Jena und Auerstedt", "Waterloo", "Leipzig"], answer: 2,
    explain: "Bei Waterloo (18. Juni 1815) unterlag Napoleon Wellington und Blücher. Danach wurde er nach St. Helena im Südatlantik verbannt, wo er 1821 starb." },
  { id: "ge2-006", cat: "geschichte", topic: "Napoleon", type: "truefalse", emoji: "📏", level: 1,
    q: "Napoleon war außergewöhnlich klein.",
    answer: false,
    explain: "Er maß etwa 1,69 m – für seine Zeit durchschnittlich. Der Mythos entstand u. a. durch die Verwechslung französischer und englischer Maßeinheiten (5 pieds 2 pouces) und durch britische Karikaturen." },
  { id: "ge2-007", cat: "geschichte", topic: "Napoleon", type: "order", emoji: "⏳", level: 2,
    q: "Bringe Napoleons Aufstieg und Fall in die richtige Reihenfolge.",
    items: ["Kaiserkrönung (1804)", "Sieg bei Austerlitz (1805)", "Russlandfeldzug (1812)", "Völkerschlacht bei Leipzig (1813)", "Waterloo (1815)"],
    explain: "Höhepunkt 1805 („Dreikaiserschlacht“), Wende 1812 in Russland, endgültiges Ende 1815 nach der Rückkehr von Elba („Herrschaft der Hundert Tage“)." },

  // ── Wiener Kongress ──
  { id: "ge2-008", cat: "geschichte", topic: "Wiener Kongress", type: "event", emoji: "🎻", level: 1, year: "1815",
    title: "Wiener Kongress ordnet Europa neu",
    text: "1814/15 verhandeln die Siegermächte unter Leitung des österreichischen Staatskanzlers **Metternich**. Leitideen: Restauration der alten Fürstenmacht, Legitimität und ein Gleichgewicht der Großmächte.",
    more: "Statt eines Nationalstaats entstand der **Deutsche Bund** – ein lockerer Bund von knapp 40 souveränen Staaten mit Bundesversammlung in Frankfurt. Spott der Zeitgenossen: „Der Kongress tanzt, aber er kommt nicht voran.“ Immerhin: Die Ordnung verhinderte fast 40 Jahre lang einen großen Krieg." },
  { id: "ge2-009", cat: "geschichte", topic: "Wiener Kongress", type: "flashcard", emoji: "🔙", level: 2,
    term: "Restauration",
    def: "Wiederherstellung der vorrevolutionären Ordnung nach 1815: Fürsten statt Volkssouveränität, Unterdrückung liberaler und nationaler Bewegungen.",
    example: "Karlsbader Beschlüsse 1819: Pressezensur, Überwachung der Universitäten, Verbot der Burschenschaften." },
  { id: "ge2-010", cat: "geschichte", topic: "Wiener Kongress", type: "truefalse", emoji: "🇩🇪", level: 1,
    q: "Der Wiener Kongress schuf 1815 einen deutschen Nationalstaat.",
    answer: false,
    explain: "Er schuf den Deutschen Bund – einen Staatenbund souveräner Fürstentümer ohne gemeinsame Regierung. Die Enttäuschung darüber trieb die Nationalbewegung bis 1848 an." },
  { id: "ge2-011", cat: "geschichte", topic: "Wiener Kongress", type: "quiz", emoji: "🤝", level: 2,
    q: "Welches Prinzip stand im Zentrum des Wiener Kongresses?",
    options: ["Volkssouveränität", "Selbstbestimmungsrecht der Nationen", "Freihandel", "Legitimität der angestammten Fürsten"], answer: 3,
    explain: "Rechtmäßig war, wer durch Erbfolge herrschte – nicht, wen das Volk wollte. Volkssouveränität und nationale Selbstbestimmung waren genau die „gefährlichen“ Ideen der Französischen Revolution, die man eindämmen wollte." },

  // ── Industrialisierung ──
  { id: "ge2-012", cat: "geschichte", topic: "Industrialisierung", type: "event", emoji: "🧾", level: 1, year: "1834",
    title: "Der Deutsche Zollverein entsteht",
    text: "Am 1. Januar 1834 fallen die Zollgrenzen zwischen 18 deutschen Staaten unter preußischer Führung. Österreich bleibt außen vor.",
    more: "Wirtschaftliche Einheit kam vor der politischen: Der Zollverein schuf einen Binnenmarkt mit rund 23 Mio. Menschen und band die Mittelstaaten an Preußen. Er nahm die „kleindeutsche Lösung“ von 1871 vorweg – ein frühes Beispiel dafür, wie Handel Politik formt (vgl. EWG)." },
  { id: "ge2-013", cat: "geschichte", topic: "Industrialisierung", type: "event", emoji: "🚂", level: 1, year: "1835",
    title: "Erste deutsche Eisenbahn: Nürnberg–Fürth",
    text: "Am 7. Dezember 1835 fährt die Lok „Adler“ die rund 6 km lange Strecke der Ludwigseisenbahn. Lok und Lokführer kamen aus England (Werkstatt Stephenson).",
    more: "Kurios: Die Bahn transportierte anfangs vor allem Personen – und zwei Fässer Bier als eine der ersten Frachten. Schon 1839 folgte mit Leipzig–Dresden die erste Fernstrecke." },
  { id: "ge2-014", cat: "geschichte", topic: "Industrialisierung", type: "number", emoji: "🛤️", level: 2,
    value: "> 60.000 km", label: "Eisenbahnnetz des Deutschen Reichs um 1913",
    text: "Von 6 km im Jahr 1835 zu einem der dichtesten Netze der Welt in weniger als 80 Jahren.",
    more: "Die Eisenbahn war Deutschlands **Leitsektor**: Sie brauchte Kohle, Eisen und Maschinen und zog damit Bergbau, Stahl- und Maschinenbau mit. Gleichzeitig senkte sie Transportkosten drastisch und ließ regionale Märkte zu einem nationalen zusammenwachsen." },
  { id: "ge2-015", cat: "geschichte", topic: "Industrialisierung", type: "quiz", emoji: "🏭", level: 2,
    q: "Welcher Sektor gilt als Leitsektor der deutschen Industrialisierung?",
    options: ["Textilindustrie", "Eisenbahnbau", "Elektroindustrie", "Landwirtschaft"], answer: 1,
    explain: "In England war die Baumwollindustrie Motor der Industrialisierung, in Deutschland der Eisenbahnbau. Chemie und Elektro (Bayer, BASF, Siemens, AEG) prägten erst die „zweite industrielle Revolution“ ab ca. 1870." },
  { id: "ge2-016", cat: "geschichte", topic: "Industrialisierung", type: "truefalse", emoji: "🇬🇧", level: 1,
    q: "Deutschland begann früher mit der Industrialisierung als England.",
    answer: false,
    explain: "England startete ab ca. 1760/70 (Dampfmaschine, mechanischer Webstuhl). Deutschland folgte mit dem „Take-off“ erst ab den 1840er-Jahren – holte dann aber schnell auf und überholte Großbritannien um 1900 bei der Stahlproduktion." },
  { id: "ge2-017", cat: "geschichte", topic: "Industrialisierung", type: "fact", emoji: "📚", level: 3,
    title: "Friedrich List: Vordenker von Zollverein und Bahnnetz",
    text: "Der Ökonom Friedrich List warb früh für einen deutschen Zollverein und entwarf 1833 ein gesamtdeutsches Eisenbahnnetz. In „Das nationale System der politischen Ökonomie“ (1841) forderte er **Erziehungszölle**.",
    more: "Idee der Erziehungszölle: Junge Industrien brauchen befristeten Schutz vor überlegener (britischer) Konkurrenz, bis sie wettbewerbsfähig sind. Das Argument taucht bis heute in Debatten über Industriepolitik und Schwellenländer auf." },
  { id: "ge2-018", cat: "geschichte", topic: "Industrialisierung", type: "whatif", emoji: "🔗", level: 2,
    q: "Was folgte aus dem Eisenbahnboom ab 1835?",
    steps: ["Riesige Nachfrage nach Kohle und Stahl", "Ruhrgebiet und Schlesien wachsen rasant", "Transportkosten sinken, Märkte verschmelzen", "Landflucht: Städte explodieren"],
    text: "Die Bahn war Nachfrager und Beschleuniger zugleich. Die Bevölkerung des Ruhrgebiets vervielfachte sich, aus Dörfern wurden Industriestädte – mit allen Folgen der „sozialen Frage“." },
  { id: "ge2-019", cat: "geschichte", topic: "Industrialisierung", type: "event", emoji: "📉", level: 3, year: "1873",
    title: "Gründerkrach beendet den Gründerboom",
    text: "Nach 1871 lösten französische Kriegsentschädigungen (5 Mrd. Francs) einen Spekulationsboom aus, Hunderte Aktiengesellschaften entstanden. Im Mai 1873 platzte die Blase mit dem Wiener Börsenkrach.",
    more: "Es folgte eine lange Phase schwachen Wachstums („Gründerkrise“). Politische Folge: Bismarck wandte sich 1879 vom Freihandel ab und führte Schutzzölle auf Getreide und Eisen ein – das Bündnis von „Roggen und Eisen“." },

  // ── Revolution 1848 ──
  { id: "ge2-020", cat: "geschichte", topic: "Revolution 1848", type: "event", emoji: "🎉", level: 2, year: "1832",
    title: "Hambacher Fest: Schwarz-Rot-Gold wird Symbol",
    text: "Am 27. Mai 1832 ziehen rund 30.000 Menschen zur Hambacher Schlossruine in der Pfalz. Sie fordern Freiheit, Volkssouveränität und nationale Einheit – unter schwarz-rot-goldenen Fahnen.",
    more: "Es war die erste politische Massenkundgebung der deutschen Geschichte. Die Farben stammen von den Uniformen des Lützowschen Freikorps der Befreiungskriege. Die Reaktion des Deutschen Bundes: noch schärfere Zensur." },
  { id: "ge2-021", cat: "geschichte", topic: "Revolution 1848", type: "event", emoji: "🏛️", level: 1, year: "1848",
    title: "Nationalversammlung in der Paulskirche",
    text: "Nach den Märzunruhen tritt am 18. Mai 1848 in der Frankfurter Paulskirche das erste frei gewählte gesamtdeutsche Parlament zusammen. Ziel: Verfassung und Nationalstaat.",
    more: "Spitzname „Professorenparlament“ – viele Juristen, Beamte und Gelehrte, kaum Arbeiter oder Bauern. Die Revolution brach zuerst in Paris (Februar 1848) aus und sprang dann auf Wien, Berlin und viele deutsche Staaten über." },
  { id: "ge2-022", cat: "geschichte", topic: "Revolution 1848", type: "event", emoji: "👑", level: 3, year: "1849",
    title: "Der preußische König lehnt die Kaiserkrone ab",
    text: "Im April 1849 bietet die Nationalversammlung Friedrich Wilhelm IV. die Krone eines Kaisers der Deutschen an. Er lehnt ab – eine Krone vom Volk sei ein „Reif aus Dreck und Letten“ mit „Ludergeruch der Revolution“.",
    more: "Damit war die Revolution gescheitert. Preußische Truppen schlugen die letzten Aufstände nieder (Festung Rastatt, Juli 1849). Viele Demokraten emigrierten, z. B. Carl Schurz, der in den USA Innenminister wurde." },
  { id: "ge2-023", cat: "geschichte", topic: "Revolution 1848", type: "quiz", emoji: "🗺️", level: 2,
    q: "Was bedeutete die „kleindeutsche Lösung“?",
    options: ["Ein Deutschland nur aus den Kleinstaaten", "Ein Bund ohne Preußen", "Eine Republik ohne Monarchen", "Ein Nationalstaat ohne Österreich, geführt von Preußen"], answer: 3,
    explain: "Die großdeutsche Lösung hätte Österreich einbezogen – scheiterte aber am Vielvölkerstaat der Habsburger. 1871 setzte Bismarck die kleindeutsche Variante durch." },
  { id: "ge2-024", cat: "geschichte", topic: "Revolution 1848", type: "truefalse", emoji: "📜", level: 2,
    q: "Die Paulskirchenverfassung trat nie in Kraft – prägte aber trotzdem das Grundgesetz.",
    answer: true,
    explain: "Ihr Grundrechtekatalog (Meinungs-, Presse-, Versammlungsfreiheit, Gleichheit vor dem Gesetz) wurde Vorbild für die Weimarer Verfassung 1919 und das Grundgesetz 1949." },
  { id: "ge2-025", cat: "geschichte", topic: "Revolution 1848", type: "order", emoji: "⏳", level: 2,
    q: "Sortiere den Weg zur Revolution und ihr Scheitern.",
    items: ["Karlsbader Beschlüsse (1819)", "Hambacher Fest (1832)", "Märzrevolution (1848)", "Paulskirche tritt zusammen (Mai 1848)", "Ablehnung der Kaiserkrone (1849)"],
    explain: "Unterdrückung (1819) → Protest (1832) → Revolution (1848) → Scheitern (1849). Die Zeit zwischen 1815 und 1848 heißt „Vormärz“." },

  // ── Soziale Frage & Marx ──
  { id: "ge2-026", cat: "geschichte", topic: "Soziale Frage", type: "event", emoji: "📕", level: 1, year: "1848",
    title: "Das Kommunistische Manifest erscheint",
    text: "Im Februar 1848 veröffentlichen Karl Marx und Friedrich Engels in London ihr Manifest: Geschichte sei eine Geschichte von Klassenkämpfen; das Proletariat werde die Bourgeoisie stürzen.",
    more: "Schlusssatz: „Proletarier aller Länder, vereinigt euch!“ Ironie: Engels, Mitautor und Geldgeber von Marx, war Fabrikantensohn und Teilhaber einer Baumwollspinnerei in Manchester. „Das Kapital“, Band 1, folgte 1867." },
  { id: "ge2-027", cat: "geschichte", topic: "Soziale Frage", type: "quiz", emoji: "🏚️", level: 1,
    q: "Was bezeichnet die „soziale Frage“ im 19. Jahrhundert?",
    options: ["Das Elend der Industriearbeiter: Hungerlöhne, Kinderarbeit, Wohnungsnot", "Den Streit um das Frauenwahlrecht", "Die Frage der Religionsfreiheit", "Den Konflikt zwischen Adel und Kirche"], answer: 0,
    explain: "12- bis 16-Stunden-Tage, keine Absicherung bei Krankheit, Unfall oder Alter, überfüllte Mietskasernen. Antworten kamen von Sozialisten (Revolution), Kirchen (Kolping, Bischof Ketteler), Unternehmern (Krupp-Werkssiedlungen) und schließlich vom Staat (Sozialversicherung)." },
  { id: "ge2-028", cat: "geschichte", topic: "Soziale Frage", type: "flashcard", emoji: "💰", level: 3,
    term: "Mehrwert (Marx)",
    def: "Differenz zwischen dem Wert, den Arbeiter erschaffen, und dem Lohn, den sie erhalten. Laut Marx eignet sich der Kapitalist diesen Mehrwert an – Kern seiner Ausbeutungstheorie.",
    example: "Ein Arbeiter schafft in 10 Stunden Waren im Wert von 10 Talern, bekommt aber nur 5 – die übrigen 5 sind Mehrwert." },
  { id: "ge2-029", cat: "geschichte", topic: "Soziale Frage", type: "event", emoji: "🌹", level: 3, year: "1863",
    title: "Lassalle gründet den ADAV – Keimzelle der SPD",
    text: "Ferdinand Lassalle gründet in Leipzig den Allgemeinen Deutschen Arbeiterverein. 1875 vereinigt er sich in Gotha mit der Partei von Bebel und Liebknecht; seit 1890 heißt sie SPD.",
    more: "Die SPD ist damit die älteste noch bestehende Partei Deutschlands. Lassalle setzte – anders als Marx – auf Reformen über den Staat, etwa durch das allgemeine Wahlrecht." },
  { id: "ge2-030", cat: "geschichte", topic: "Soziale Frage", type: "truefalse", emoji: "👦", level: 3,
    q: "Preußen verbot schon 1839 Fabrikarbeit für Kinder unter 9 Jahren.",
    answer: true,
    explain: "Das „Regulativ“ von 1839 war das erste deutsche Arbeitsschutzgesetz. Ein Grund: Das Militär klagte, dass zu viele Rekruten aus Industriegebieten untauglich seien." },

  // ── Bismarck & Kaiserreich ──
  { id: "ge2-031", cat: "geschichte", topic: "Kaiserreich", type: "order", emoji: "⚔️", level: 2,
    q: "Sortiere Bismarcks Einigungskriege bis zur Reichsgründung.",
    items: ["Deutsch-Dänischer Krieg (1864)", "Deutscher Krieg gegen Österreich (1866)", "Deutsch-Französischer Krieg (1870)", "Kaiserproklamation (1871)"],
    explain: "1866 entschied die Schlacht bei Königgrätz die Vorherrschaft in Deutschland zugunsten Preußens. Der Krieg gegen Frankreich 1870/71 brachte die süddeutschen Staaten ins Boot." },
  { id: "ge2-032", cat: "geschichte", topic: "Kaiserreich", type: "event", emoji: "🪞", level: 1, year: "1871",
    title: "Kaiserproklamation im Spiegelsaal von Versailles",
    text: "Am 18. Januar 1871 wird der preußische König Wilhelm I. im Schloss von Versailles zum Deutschen Kaiser ausgerufen – mitten im besiegten Frankreich. Das Deutsche Reich ist gegründet.",
    more: "Eine bewusste Demütigung Frankreichs, die sich rächte: 1919 musste Deutschland den Versailler Vertrag im selben Spiegelsaal unterschreiben. Frankreich verlor 1871 außerdem Elsass-Lothringen – ein Dauerkonflikt bis 1918." },
  { id: "ge2-033", cat: "geschichte", topic: "Kaiserreich", type: "flashcard", emoji: "🩸", level: 3,
    term: "„Blut und Eisen“",
    def: "Bismarcks Rede vor der Budgetkommission 1862: Die großen Fragen der Zeit würden nicht durch Reden und Mehrheitsbeschlüsse entschieden, sondern durch „Eisen und Blut“.",
    example: "Sinnbild seiner Realpolitik: Einigung durch Kriege und Machtpolitik statt durch Parlament und Revolution wie 1848." },
  { id: "ge2-034", cat: "geschichte", topic: "Kaiserreich", type: "event", emoji: "🏥", level: 1, year: "1883",
    title: "Bismarcks Sozialversicherung startet",
    text: "1883 Krankenversicherung, 1884 Unfallversicherung, 1889 Invaliditäts- und Altersversicherung: Deutschland baut als erstes Land der Welt eine staatliche Sozialversicherung auf.",
    more: "Motiv war nicht nur Fürsorge: Die Arbeiter sollten vom Sozialismus weggelockt und an den Staat gebunden werden. Das Prinzip – Beiträge von Arbeitgebern und Arbeitnehmern – gilt bis heute. Arbeitslosenversicherung kam erst 1927, Pflegeversicherung 1995." },
  { id: "ge2-035", cat: "geschichte", topic: "Kaiserreich", type: "number", emoji: "👴", level: 2,
    value: "70 Jahre", label: "Rentenalter in Bismarcks Altersversicherung 1889",
    text: "Rente gab es erst ab 70 – ein Alter, das damals nur eine Minderheit der Arbeiter erreichte.",
    more: "1916 wurde die Altersgrenze auf 65 gesenkt. Heute steigt sie schrittweise auf 67 – weil Menschen viel länger leben und länger Rente beziehen. Die Rente war ursprünglich eher ein Zuschuss als eine Vollversorgung." },
  { id: "ge2-036", cat: "geschichte", topic: "Kaiserreich", type: "fact", emoji: "🍬", level: 2,
    title: "Zuckerbrot und Peitsche",
    text: "Bismarcks Doppelstrategie gegen die Arbeiterbewegung: Das **Sozialistengesetz** (1878–1890) verbot sozialdemokratische Vereine und Zeitungen; gleichzeitig sollte die **Sozialversicherung** die Arbeiter versöhnen.",
    more: "Ergebnis: Die Peitsche wirkte nicht. Die SPD wuchs trotz Verbots (Kandidaten durften weiter antreten) und wurde 1912 stärkste Fraktion im Reichstag. Das Zuckerbrot dagegen wurde zum Weltmodell." },
  { id: "ge2-037", cat: "geschichte", topic: "Kaiserreich", type: "quiz", emoji: "🕸️", level: 2,
    q: "Was war das Hauptziel von Bismarcks Bündnispolitik nach 1871?",
    options: ["Kolonien in Afrika zu erwerben", "Österreich zu schwächen", "Eine Allianz mit Großbritannien gegen Russland", "Frankreich isolieren und Zweifrontenkrieg vermeiden"], answer: 3,
    explain: "Bismarck sah das Reich als „saturiert“. Mit einem Netz aus Bündnissen (Zweibund 1879, Rückversicherungsvertrag mit Russland 1887) hielt er Frankreich isoliert. Nach seiner Entlassung 1890 ließ man den Rückversicherungsvertrag auslaufen – Russland verbündete sich 1894 mit Frankreich." },
  { id: "ge2-038", cat: "geschichte", topic: "Kaiserreich", type: "event", emoji: "⚓", level: 3, year: "1890",
    title: "Der Lotse geht von Bord",
    text: "Der junge Kaiser Wilhelm II. entlässt Bismarck im März 1890. Die berühmte Karikatur im britischen Magazin „Punch“ zeigt den Kanzler als Lotsen, der das Schiff verlässt.",
    more: "Wilhelm II. setzte auf einen „Neuen Kurs“: Weltpolitik, Flottenbau, Kolonien. Das komplizierte Bündnissystem Bismarcks zerfiel – Deutschland fühlte sich bald „eingekreist“." },
  { id: "ge2-039", cat: "geschichte", topic: "Kaiserreich", type: "truefalse", emoji: "⛪", level: 2,
    q: "Im „Kulturkampf“ der 1870er-Jahre kämpfte Bismarck gegen die katholische Kirche.",
    answer: true,
    explain: "Er sah im Katholizismus und der Zentrumspartei eine Gefahr für das protestantisch-preußisch geprägte Reich. Ein bleibendes Ergebnis: Seit 1875 ist in Deutschland die standesamtliche Zivilehe Pflicht." },

  // ── Imperialismus ──
  { id: "ge2-040", cat: "geschichte", topic: "Imperialismus", type: "event", emoji: "🌍", level: 2, year: "1884",
    title: "Berliner Kongokonferenz",
    text: "Auf Einladung Bismarcks legen 1884/85 europäische Mächte und die USA in Berlin Regeln für die Inbesitznahme Afrikas fest. Kein einziger Afrikaner sitzt am Tisch.",
    more: "Folge war der „Wettlauf um Afrika“. Das Kongobecken fiel als Privatbesitz an den belgischen König Leopold II. – sein Ausbeutungsregime (Kautschuk) kostete Millionen Menschen das Leben. Viele heutige Grenzen Afrikas sind mit dem Lineal gezogene Kolonialgrenzen." },
  { id: "ge2-041", cat: "geschichte", topic: "Imperialismus", type: "truefalse", emoji: "🗺️", level: 1,
    q: "Um 1914 waren fast alle Gebiete Afrikas unter europäischer Kolonialherrschaft.",
    answer: true,
    explain: "Nur Äthiopien (siegte 1896 bei Adua gegen Italien) und Liberia blieben unabhängig. Rund 90 % des Kontinents waren aufgeteilt." },
  { id: "ge2-042", cat: "geschichte", topic: "Imperialismus", type: "event", emoji: "🕯️", level: 2, year: "1904",
    title: "Völkermord an Herero und Nama",
    text: "In Deutsch-Südwestafrika (heute Namibia) schlagen deutsche Truppen einen Aufstand nieder. General von Trotha erlässt einen Vernichtungsbefehl; Zehntausende sterben in der Wüste und in Lagern.",
    more: "Es gilt als erster Völkermord des 20. Jahrhunderts. Die Bundesregierung hat die Verbrechen 2021 politisch als Völkermord anerkannt. Deutschland besaß Kolonien nur von 1884 bis 1919 – mit Versailles gingen alle verloren." },
  { id: "ge2-043", cat: "geschichte", topic: "Imperialismus", type: "quiz", emoji: "☀️", level: 3,
    q: "Wer forderte 1897 im Reichstag für Deutschland einen „Platz an der Sonne“?",
    options: ["Otto von Bismarck", "Bernhard von Bülow", "Alfred von Tirpitz", "Kaiser Wilhelm II."], answer: 1,
    explain: "Bülow, damals Staatssekretär im Auswärtigen Amt, später Reichskanzler: „Wir wollen niemand in den Schatten stellen, aber wir verlangen auch unseren Platz an der Sonne.“ Ein Schlagwort für die wilhelminische Weltpolitik." },
  { id: "ge2-044", cat: "geschichte", topic: "Imperialismus", type: "fact", emoji: "🚢", level: 3,
    title: "Flottenwettrüsten mit Großbritannien",
    text: "Mit den Flottengesetzen ab 1898 ließ Admiral **Tirpitz** eine Schlachtflotte bauen, die Großbritannien herausfordern sollte. London antwortete mit eigenem Aufrüsten (Dreadnought, 1906).",
    more: "Strategischer Fehlgriff: Großbritannien rückte an die Seite Frankreichs (Entente cordiale 1904) und Russlands (1907). So entstanden die Blöcke, die 1914 gegeneinander standen – die deutsche Flotte blieb im Krieg dagegen weitgehend im Hafen." },

  // ── Erster Weltkrieg ──
  { id: "ge2-045", cat: "geschichte", topic: "Erster Weltkrieg", type: "event", emoji: "🔫", level: 1, year: "1914",
    title: "Attentat von Sarajevo",
    text: "Am 28. Juni 1914 erschießt der bosnisch-serbische Nationalist Gavrilo Princip den österreichischen Thronfolger Franz Ferdinand und dessen Frau Sophie in Sarajevo.",
    more: "Kurios: Ein erster Bombenanschlag am selben Morgen war gescheitert. Erst als der Fahrer sich verfuhr und direkt vor Princip anhielt, kam es zu den tödlichen Schüssen. Das Attentat war Anlass, nicht Ursache des Krieges: Bündnisblöcke, Wettrüsten, Nationalismus und Imperialismus hatten den Boden bereitet." },
  { id: "ge2-046", cat: "geschichte", topic: "Erster Weltkrieg", type: "order", emoji: "📅", level: 3,
    q: "Sortiere die Julikrise 1914.",
    items: ["Attentat von Sarajevo (28. Juni)", "Deutscher „Blankoscheck“ an Wien (5./6. Juli)", "Ultimatum Österreichs an Serbien (23. Juli)", "Österreich erklärt Serbien den Krieg (28. Juli)", "Deutschland erklärt Russland den Krieg (1. August)"],
    explain: "In nur fünf Wochen wurde aus einem regionalen Konflikt ein Weltkrieg: Russland stützte Serbien, Deutschland Österreich, Frankreich war mit Russland verbündet, und mit dem Einmarsch in Belgien kam Großbritannien hinzu." },
  { id: "ge2-047", cat: "geschichte", topic: "Erster Weltkrieg", type: "flashcard", emoji: "📝", level: 3,
    term: "Blankoscheck",
    def: "Zusage der deutschen Reichsleitung Anfang Juli 1914, Österreich-Ungarn bei einem Vorgehen gegen Serbien bedingungslos zu unterstützen – auch wenn Russland eingreift.",
    example: "Ohne diese Rückendeckung hätte Wien kaum ein so hartes Ultimatum an Serbien gestellt. Zentral für die Debatte um die deutsche Kriegsschuld (Fischer-Kontroverse der 1960er)." },
  { id: "ge2-048", cat: "geschichte", topic: "Erster Weltkrieg", type: "whatif", emoji: "🇧🇪", level: 2,
    q: "Was folgte aus dem deutschen Schlieffenplan im August 1914?",
    steps: ["Plan: Frankreich schnell über Belgien besiegen", "Einmarsch ins neutrale Belgien", "Großbritannien erklärt Deutschland den Krieg", "Vormarsch stoppt an der Marne", "Erstarrung im Stellungskrieg"],
    text: "Der Plan sollte einen Zweifrontenkrieg vermeiden: erst Frankreich in wenigen Wochen schlagen, dann gegen Russland. Die Verletzung der belgischen Neutralität brachte Großbritannien in den Krieg, und nach der Marneschlacht (September 1914) erstarrte die Westfront für fast vier Jahre." },
  { id: "ge2-049", cat: "geschichte", topic: "Erster Weltkrieg", type: "event", emoji: "💀", level: 2, year: "1916",
    title: "Verdun: Die „Blutpumpe“",
    text: "Von Februar bis Dezember 1916 kämpfen deutsche und französische Truppen um die Festung Verdun. Rund 300.000 Soldaten sterben, die Front bewegt sich am Ende kaum.",
    more: "Verdun wurde Symbol für die Sinnlosigkeit des Stellungskrieges. 1984 reichten sich Kohl und Mitterrand dort die Hände – ein ikonisches Bild der deutsch-französischen Versöhnung." },
  { id: "ge2-050", cat: "geschichte", topic: "Erster Weltkrieg", type: "event", emoji: "🇺🇸", level: 2, year: "1917",
    title: "Die USA treten in den Krieg ein",
    text: "Im April 1917 erklären die USA Deutschland den Krieg. Auslöser: der uneingeschränkte U-Boot-Krieg und das abgefangene **Zimmermann-Telegramm**, in dem Deutschland Mexiko ein Bündnis gegen die USA anbot.",
    more: "Mexiko sollte im Gegenzug Texas, New Mexico und Arizona zurückbekommen. Der Kriegseintritt der USA mit ihren enormen Ressourcen entschied den Krieg. 1917 ist ein Doppelwendejahr: USA rein, Russland (Revolution) bald raus." },
  { id: "ge2-051", cat: "geschichte", topic: "Erster Weltkrieg", type: "quiz", emoji: "🕊️", level: 1,
    q: "Wann trat der Waffenstillstand in Kraft, der den Ersten Weltkrieg beendete?",
    options: ["11. November 1918", "9. November 1918", "28. Juni 1919", "1. August 1918"], answer: 0,
    explain: "Unterzeichnet im Eisenbahnwaggon von Compiègne, gültig ab 11 Uhr am 11.11.1918. Großbritannien und Frankreich gedenken bis heute an diesem Tag (Remembrance/Armistice Day)." },
  { id: "ge2-052", cat: "geschichte", topic: "Erster Weltkrieg", type: "number", emoji: "⚰️", level: 1,
    value: "≈ 17 Mio.", label: "Tote des Ersten Weltkriegs (Soldaten und Zivilisten)",
    text: "Schätzungen reichen von 15 bis über 20 Millionen. Allein rund 2 Mio. deutsche Soldaten fielen.",
    more: "In Frankreich und Großbritannien heißt er bis heute „Der Große Krieg“. Maschinengewehre, Artillerie, Giftgas (erstmals 1915 bei Ypern) und Panzer machten ihn zum ersten industrialisierten Massenkrieg. Der US-Diplomat George Kennan nannte ihn die „Urkatastrophe“ des 20. Jahrhunderts." },
  { id: "ge2-053", cat: "geschichte", topic: "Erster Weltkrieg", type: "event", emoji: "✍️", level: 1, year: "1919",
    title: "Der Versailler Vertrag",
    text: "Am 28. Juni 1919 muss Deutschland unterschreiben: Gebietsverluste (u. a. Elsass-Lothringen, Westpreußen, Posen), Verlust aller Kolonien, Heer auf 100.000 Mann begrenzt, hohe Reparationen und Art. 231 – die Alleinschuld am Krieg.",
    more: "Deutschland durfte nicht mitverhandeln – daher „Diktatfrieden“. Ökonom John Maynard Keynes warnte schon 1919 in „Die wirtschaftlichen Folgen des Friedens“, die Reparationen würden Europa destabilisieren." },
  { id: "ge2-054", cat: "geschichte", topic: "Erster Weltkrieg", type: "quiz", emoji: "🪖", level: 2,
    q: "Wie groß durfte das deutsche Heer nach dem Versailler Vertrag höchstens sein?",
    options: ["50.000 Mann", "250.000 Mann", "100.000 Mann", "500.000 Mann"], answer: 2,
    explain: "Dazu: keine Luftwaffe, keine U-Boote, keine Panzer, keine Wehrpflicht, das Rheinland entmilitarisiert. Hitler brach diese Auflagen ab 1935 offen (Wehrpflicht) und 1936 (Rheinlandbesetzung)." },
  { id: "ge2-055", cat: "geschichte", topic: "Erster Weltkrieg", type: "truefalse", emoji: "💶", level: 3,
    q: "Deutschland hat die letzten Zahlungen im Zusammenhang mit dem Versailler Vertrag erst 2010 geleistet.",
    answer: true,
    explain: "Am 3. Oktober 2010 wurden die letzten Zinsen auf Anleihen beglichen, mit denen in den 1920ern Reparationen finanziert worden waren. Das Londoner Schuldenabkommen von 1953 hatte die Zahlung bis zur Wiedervereinigung aufgeschoben." },
  { id: "ge2-056", cat: "geschichte", topic: "Erster Weltkrieg", type: "fact", emoji: "🗡️", level: 2,
    title: "Die Dolchstoßlegende",
    text: "Nach 1918 verbreiteten Militärs und Nationalisten die Lüge, das deutsche Heer sei „im Felde unbesiegt“ gewesen und nur durch Verrat der Heimat – Sozialdemokraten, Linke, Juden – zu Fall gebracht worden.",
    more: "Tatsächlich hatte die Oberste Heeresleitung selbst im September 1918 einen Waffenstillstand verlangt, weil die Front zusammenbrach. Die Legende belastete die Weimarer Republik von Anfang an und wurde zentral für die NS-Propaganda." },

  // ── Russische Revolution ──
  { id: "ge2-057", cat: "geschichte", topic: "Russische Revolution", type: "event", emoji: "☭", level: 1, year: "1917",
    title: "Oktoberrevolution: Lenin übernimmt die Macht",
    text: "Nach dem Sturz des Zaren im Februar 1917 erobern die Bolschewiki unter Lenin in der Nacht zum 7. November (nach altem Kalender: 25. Oktober) Petrograd und stürzen die Provisorische Regierung.",
    more: "Die deutsche Regierung hatte Lenin im April 1917 im „plombierten Zug“ aus dem Schweizer Exil nach Russland gebracht – in der Hoffnung, er werde Russland aus dem Krieg nehmen. Das klappte: Im März 1918 folgte der Separatfrieden von Brest-Litowsk." },
  { id: "ge2-058", cat: "geschichte", topic: "Russische Revolution", type: "truefalse", emoji: "📆", level: 2,
    q: "Die Oktoberrevolution fand nach unserem Kalender im November statt.",
    answer: true,
    explain: "Russland nutzte noch den julianischen Kalender, 13 Tage hinter dem gregorianischen. Die Bolschewiki stellten 1918 um – seither wurde der „Oktoberrevolution“ jedes Jahr am 7. November gedacht." },
  { id: "ge2-059", cat: "geschichte", topic: "Russische Revolution", type: "quiz", emoji: "🧔", level: 1,
    q: "Wer setzte sich nach Lenins Tod 1924 als Alleinherrscher der Sowjetunion durch?",
    options: ["Josef Stalin", "Leo Trotzki", "Nikita Chruschtschow", "Grigori Sinowjew"], answer: 0,
    explain: "Stalin schaltete seine Rivalen aus – Trotzki wurde verbannt und 1940 in Mexiko ermordet. Sein Terror (Großer Terror 1936–38, Gulag) kostete Millionen Menschen das Leben." },
  { id: "ge2-060", cat: "geschichte", topic: "Russische Revolution", type: "fact", emoji: "🌾", level: 3,
    title: "Holodomor: Hunger als Waffe",
    text: "Stalins Zwangskollektivierung der Landwirtschaft und überhöhte Ablieferungsquoten führten 1932/33 zu einer Hungersnot, die in der Ukraine Millionen Menschen tötete (Schätzungen: 3,5 bis 5 Mio.).",
    more: "„Holodomor“ heißt „Tötung durch Hunger“. Der Bundestag hat ihn 2022 als Völkermord eingestuft. Das Thema prägt das ukrainische Geschichtsbewusstsein und das Verhältnis zu Russland bis heute." },

  // ── Weimarer Republik ──
  { id: "ge2-061", cat: "geschichte", topic: "Weimarer Republik", type: "event", emoji: "🪟", level: 1, year: "1918",
    title: "Gleich zweimal wird die Republik ausgerufen",
    text: "Am 9. November 1918 ruft Philipp Scheidemann (SPD) vom Reichstagsfenster die „deutsche Republik“ aus. Zwei Stunden später proklamiert Karl Liebknecht am Berliner Schloss die „freie sozialistische Republik“.",
    more: "Der Kaiser floh ins niederländische Exil. Die Doppel-Ausrufung zeigt den Konflikt von Anfang an: parlamentarische Demokratie oder Räterepublik nach russischem Vorbild. Die SPD setzte sich durch – mit Hilfe des alten Militärs." },
  { id: "ge2-062", cat: "geschichte", topic: "Weimarer Republik", type: "quiz", emoji: "📅", level: 2,
    q: "Welches Ereignis fand NICHT an einem 9. November statt?",
    options: ["Mauerbau in Berlin", "Ausrufung der Republik", "Hitlerputsch in München", "Novemberpogrome"], answer: 0,
    explain: "Die Mauer wurde am 13. August 1961 gebaut – sie fiel am 9. November 1989. Daher heißt der 9. November „Schicksalstag der Deutschen“: 1918, 1923, 1938, 1989." },
  { id: "ge2-063", cat: "geschichte", topic: "Weimarer Republik", type: "fact", emoji: "📜", level: 3,
    title: "Weimarer Verfassung: modern – mit Konstruktionsfehlern",
    text: "Die Verfassung von 1919 brachte Frauenwahlrecht und Grundrechte. Doch der direkt gewählte Reichspräsident war ein „Ersatzkaiser“: Er konnte per **Art. 48** Notverordnungen erlassen und den Reichstag auflösen.",
    more: "Dazu kam reines Verhältniswahlrecht ohne Sperrklausel – bis zu 15 Parteien im Reichstag. Das Grundgesetz zog Lehren: schwacher Bundespräsident, konstruktives Misstrauensvotum, 5 %-Hürde (ab 1953 bundesweit), wehrhafte Demokratie." },
  { id: "ge2-064", cat: "geschichte", topic: "Weimarer Republik", type: "truefalse", emoji: "🗳️", level: 1,
    q: "Frauen durften in Deutschland zum ersten Mal 1919 wählen.",
    answer: true,
    explain: "Bei der Wahl zur Nationalversammlung am 19. Januar 1919 wählten und kandidierten Frauen erstmals reichsweit. Beschlossen wurde das Frauenwahlrecht bereits im November 1918. Die Schweiz führte es auf Bundesebene erst 1971 ein." },
  { id: "ge2-065", cat: "geschichte", topic: "Weimarer Republik", type: "event", emoji: "💸", level: 1, year: "1923",
    title: "Hyperinflation: Geld wird Altpapier",
    text: "Im November 1923 kostet ein US-Dollar 4,2 Billionen Mark. Löhne werden täglich ausgezahlt und sofort ausgegeben, Banknoten dienen als Heizmaterial und Kinderspielzeug.",
    more: "Die Rentenmark beendete den Spuk (1 Rentenmark = 1 Billion Papiermark). Die Erfahrung brannte sich ins kollektive Gedächtnis – sie erklärt, warum in Deutschland Preisstabilität und eine unabhängige Notenbank (Bundesbank, EZB) bis heute fast heilig sind." },
  { id: "ge2-066", cat: "geschichte", topic: "Weimarer Republik", type: "number", emoji: "🍞", level: 2,
    value: "200 Mrd. Mark", label: "Preis für ein Brot in Berlin im November 1923",
    text: "Anfang 1919 kostete ein Brot noch unter einer Mark. Gedruckt wurde von rund 130 Druckereien – Tag und Nacht.",
    more: "Verlierer waren Sparer und die Mittelschicht, deren Ersparnisse sich auflösten. Gewinner waren Schuldner – inklusive des Staates, der seine Kriegsanleihen faktisch loswurde – und Sachwertbesitzer wie Unternehmer und Grundbesitzer." },
  { id: "ge2-067", cat: "geschichte", topic: "Weimarer Republik", type: "whatif", emoji: "🖨️", level: 2,
    q: "Was folgte aus der Ruhrbesetzung 1923?",
    steps: ["Frankreich besetzt das Ruhrgebiet", "Regierung ruft passiven Widerstand aus", "Streikende werden mit Notenpresse bezahlt", "Geldmenge explodiert – Hyperinflation", "Mittelschicht verliert ihre Ersparnisse"],
    text: "Frankreich und Belgien besetzten im Januar 1923 das Ruhrgebiet, weil Deutschland mit Reparationen (Kohle, Holz) im Rückstand war. Der Staat finanzierte den Generalstreik durch Gelddrucken – die bereits laufende Inflation geriet völlig außer Kontrolle." },
  { id: "ge2-068", cat: "geschichte", topic: "Weimarer Republik", type: "quiz", emoji: "💵", level: 2,
    q: "Mit welcher Währung wurde die Hyperinflation im November 1923 gestoppt?",
    options: ["Deutsche Mark", "Goldmark", "Reichsmark", "Rentenmark"], answer: 3,
    explain: "Die Rentenmark war formal durch eine Grundschuld auf Landwirtschaft und Industrie gedeckt – entscheidend war aber das Vertrauen und die strikte Begrenzung der Geldmenge. 1924 löste die Reichsmark sie ab." },
  { id: "ge2-069", cat: "geschichte", topic: "Weimarer Republik", type: "event", emoji: "🍺", level: 2, year: "1923",
    title: "Hitlerputsch in München scheitert",
    text: "Am 8./9. November 1923 versucht Hitler mit Ludendorff, von München aus die Reichsregierung zu stürzen. Der Marsch zur Feldherrnhalle wird von der Polizei gestoppt.",
    more: "Hitler wurde zu fünf Jahren Festungshaft verurteilt, kam aber nach neun Monaten frei. In der Haft in Landsberg diktierte er „Mein Kampf“. Lehre für ihn: Macht nicht durch Putsch, sondern „legal“ über Wahlen erobern." },
  { id: "ge2-070", cat: "geschichte", topic: "Weimarer Republik", type: "fact", emoji: "🎷", level: 3,
    title: "Goldene Zwanziger: Blüte auf Pump",
    text: "1924–1929 stabilisiert sich die Republik: Der **Dawes-Plan** ordnet die Reparationen, US-Kredite fließen, Außenminister Stresemann versöhnt sich mit Frankreich (Locarno 1925, Völkerbund 1926). Berlin wird Kulturmetropole.",
    more: "Bauhaus, Kino („Metropolis“), Kabarett, Jazz. Die Schwäche: Viele US-Kredite waren kurzfristig. Als sie 1929 abgezogen wurden, brach das Kartenhaus zusammen. Merke: Geld aus den USA → Reparationen an Frankreich/GB → Kriegsschulden zurück an die USA – ein Kreislauf." },
  { id: "ge2-071", cat: "geschichte", topic: "Weltwirtschaftskrise", type: "event", emoji: "📉", level: 1, year: "1929",
    title: "Schwarzer Donnerstag an der Wall Street",
    text: "Am 24. Oktober 1929 bricht die New Yorker Börse ein; am „Schwarzen Dienstag“ (29. Oktober) folgt der nächste Absturz. Eine weltweite Depression beginnt.",
    more: "In Europa heißt er „Schwarzer Freitag“, weil die Nachricht wegen der Zeitverschiebung erst am Freitag ankam. Bis 1932 fiel der Dow Jones um rund 89 % vom Höchststand. Fehlerhafte Politik (Goldstandard, Schutzzölle wie der Smoot-Hawley Tariff Act 1930) verschärfte die Krise weltweit." },
  { id: "ge2-072", cat: "geschichte", topic: "Weltwirtschaftskrise", type: "number", emoji: "🧍", level: 1,
    value: "6 Mio.", label: "Offiziell registrierte Arbeitslose in Deutschland Anfang 1932",
    text: "Rund jeder dritte Erwerbstätige war ohne Arbeit; die Dunkelziffer lag noch höher.",
    more: "Massenarbeitslosigkeit war der Treibstoff der Radikalen: Die NSDAP stieg von 2,6 % (1928) auf 37,3 % (Juli 1932), auch die KPD legte zu. Wirtschaftskrise und Demokratiekrise hängen eng zusammen – eine Lehre, die die Krisenpolitik bis 2008 und 2020 prägte." },
  { id: "ge2-073", cat: "geschichte", topic: "Weltwirtschaftskrise", type: "whatif", emoji: "⛓️", level: 3,
    q: "Was folgte in Deutschland aus dem Börsenkrach 1929?",
    steps: ["US-Banken ziehen kurzfristige Kredite ab", "Firmenpleiten und Bankenkrise (1931)", "Brüning spart und senkt Löhne und Preise", "Krise verschärft sich, 6 Mio. Arbeitslose", "Radikale Parteien gewinnen massiv"],
    text: "Reichskanzler Brüning setzte auf Deflation: Ausgaben kürzen, Steuern erhöhen – auch, um die Unbezahlbarkeit der Reparationen zu beweisen. Die Sparpolitik per Notverordnung vertiefte die Krise. Die Reparationen wurden 1932 in Lausanne tatsächlich faktisch beendet – zu spät für die Republik." },
  { id: "ge2-074", cat: "geschichte", topic: "Weltwirtschaftskrise", type: "flashcard", emoji: "🏛️", level: 3,
    term: "Präsidialkabinett",
    def: "Regierung ohne Parlamentsmehrheit, die sich allein auf das Vertrauen des Reichspräsidenten und dessen Notverordnungsrecht (Art. 48) stützt.",
    example: "1930–1933: Brüning, von Papen, von Schleicher. Der Reichstag wurde dabei zunehmend ausgeschaltet – die Demokratie war schon vor Hitler ausgehöhlt." },
  { id: "ge2-075", cat: "geschichte", topic: "Weltwirtschaftskrise", type: "fact", emoji: "🦅", level: 2,
    title: "New Deal: Roosevelts Antwort auf die Krise",
    text: "Ab 1933 bekämpfte US-Präsident Franklin D. Roosevelt die Depression mit staatlichen Arbeitsprogrammen, Bankenregulierung (Glass-Steagall Act), Einlagensicherung und der Einführung der Sozialversicherung (1935).",
    more: "Ein Gegenmodell zu Brünings Sparkurs: Der Staat stemmt sich mit Ausgaben gegen die Krise – Keynes lieferte 1936 die Theorie dazu. Roosevelt wurde als einziger US-Präsident viermal gewählt; seit 1951 sind nur noch zwei Amtszeiten erlaubt." },
  { id: "ge2-076", cat: "geschichte", topic: "Weimarer Republik", type: "truefalse", emoji: "📊", level: 2,
    q: "Die NSDAP gewann bei einer freien Reichstagswahl nie die absolute Mehrheit.",
    answer: true,
    explain: "Ihr bestes freies Ergebnis waren 37,3 % im Juli 1932; im November 1932 fiel sie auf 33,1 %. Selbst bei der schon unfreien Wahl im März 1933 kam sie nur auf 43,9 %. Hitler kam durch Ernennung an die Macht, nicht durch eine Mehrheit." },
  { id: "ge2-077", cat: "geschichte", topic: "Weimarer Republik", type: "order", emoji: "⏳", level: 1,
    q: "Sortiere die Stationen der Weimarer Republik.",
    items: ["Ausrufung der Republik (1918)", "Hyperinflation (1923)", "Vertrag von Locarno (1925)", "Weltwirtschaftskrise beginnt (1929)", "Hitler wird Reichskanzler (1933)"],
    explain: "Merke drei Phasen: Krisenjahre 1918–1923, „Goldene Zwanziger“ 1924–1929, Auflösung 1930–1933." },

  // ── NS-Diktatur ──
  { id: "ge2-078", cat: "geschichte", topic: "NS-Diktatur", type: "event", emoji: "🕯️", level: 1, year: "1933",
    title: "Hitler wird Reichskanzler",
    text: "Am 30. Januar 1933 ernennt Reichspräsident Hindenburg Adolf Hitler zum Reichskanzler – an der Spitze eines Kabinetts mit nur drei NSDAP-Mitgliedern.",
    more: "Die konservativen Steigbügelhalter glaubten, Hitler „einrahmen“ zu können. Franz von Papen: „Wir haben ihn uns engagiert.“ In weniger als zwei Monaten war die Demokratie beseitigt – ein Lehrstück über die Unterschätzung von Extremisten." },
  { id: "ge2-079", cat: "geschichte", topic: "NS-Diktatur", type: "event", emoji: "🔥", level: 2, year: "1933",
    title: "Reichstagsbrand und Notverordnung",
    text: "In der Nacht zum 28. Februar 1933 brennt der Reichstag. Schon am nächsten Tag setzt die „Reichstagsbrandverordnung“ die Grundrechte außer Kraft – dauerhaft bis 1945.",
    more: "Der Niederländer Marinus van der Lubbe wurde als Täter gefasst; die Nazis nutzten den Brand sofort, um Tausende Kommunisten und Sozialdemokraten zu verhaften. Die Verordnung war die eigentliche „Verfassungsurkunde“ des Dritten Reichs." },
  { id: "ge2-080", cat: "geschichte", topic: "NS-Diktatur", type: "event", emoji: "⚖️", level: 1, year: "1933",
    title: "Das Ermächtigungsgesetz",
    text: "Am 23. März 1933 erlaubt der Reichstag der Regierung, Gesetze ohne Parlament zu erlassen – selbst verfassungsändernde. Nur die SPD stimmt dagegen; die KPD-Abgeordneten waren bereits verhaftet oder geflohen.",
    more: "Otto Wels (SPD) in seiner letzten freien Rede: „Freiheit und Leben kann man uns nehmen, die Ehre nicht.“ Auch Zentrum und Liberale stimmten zu – auch der spätere Bundespräsident Theodor Heuss. Lehre fürs Grundgesetz: Ewigkeitsklausel (Art. 79 Abs. 3)." },
  { id: "ge2-081", cat: "geschichte", topic: "NS-Diktatur", type: "flashcard", emoji: "🔩", level: 1,
    term: "Gleichschaltung",
    def: "Ausrichtung aller Institutionen auf die NS-Ideologie ab 1933: Länder entmachtet, Gewerkschaften zerschlagen (2. Mai 1933), alle Parteien außer der NSDAP verboten (Juli 1933).",
    example: "Auch Vereine, Presse, Justiz und Universitäten wurden „gleichgeschaltet“ – bis zum Kaninchenzüchterverein." },
  { id: "ge2-082", cat: "geschichte", topic: "NS-Diktatur", type: "event", emoji: "🗡️", level: 3, year: "1934",
    title: "„Röhm-Putsch“ und Führerstaat",
    text: "Am 30. Juni 1934 lässt Hitler SA-Chef Ernst Röhm und Dutzende Rivalen ermorden. Nach Hindenburgs Tod am 2. August vereint er die Ämter von Kanzler und Präsident: „Führer und Reichskanzler“.",
    more: "Der „Putsch“ war eine Propagandalüge – es gab keinen. Die Reichswehr, erleichtert über die Ausschaltung der SA-Konkurrenz, schwor nun einen persönlichen Eid auf Hitler. Damit war die Machtergreifung abgeschlossen." },
  { id: "ge2-083", cat: "geschichte", topic: "NS-Diktatur", type: "event", emoji: "📜", level: 1, year: "1935",
    title: "Die Nürnberger Gesetze",
    text: "Am 15. September 1935 beschließt der Reichstag auf dem NSDAP-Parteitag das „Reichsbürgergesetz“ und das „Blutschutzgesetz“. Juden werden zu Bürgern zweiter Klasse, Ehen mit „Ariern“ verboten.",
    more: "Die Gesetze lieferten die pseudorechtliche Grundlage für die schrittweise Entrechtung: Berufsverbote, Enteignung („Arisierung“), Ausgrenzung – bis zur Deportation. Wer als Jude galt, legte das Regime über die Religion der Großeltern fest." },
  { id: "ge2-084", cat: "geschichte", topic: "NS-Diktatur", type: "event", emoji: "🔥", level: 1, year: "1938",
    title: "Novemberpogrome",
    text: "In der Nacht vom 9. auf den 10. November 1938 zerstören SA, SS und Mitläufer über 1.400 Synagogen und Betstuben und Tausende jüdische Geschäfte. Hunderte Menschen sterben, rund 30.000 jüdische Männer kommen in KZ.",
    more: "Die Nazis nannten es „Reichskristallnacht“ – ein verharmlosender Begriff. Zynisch: Den Juden wurde anschließend eine „Sühneleistung“ von 1 Mrd. Reichsmark auferlegt. Der Pogrom markiert den Übergang von Diskriminierung zu offener Gewalt." },
  { id: "ge2-085", cat: "geschichte", topic: "NS-Diktatur", type: "event", emoji: "🏚️", level: 2, year: "1942",
    title: "Die Wannseekonferenz",
    text: "Am 20. Januar 1942 koordinieren 15 hochrangige Beamte und SS-Führer unter Reinhard Heydrich in einer Berliner Villa die „Endlösung der Judenfrage“ – die Ermordung der europäischen Juden.",
    more: "Der Massenmord hatte schon begonnen (Erschießungen in der Sowjetunion seit 1941). Die Konferenz organisierte die Zusammenarbeit der Bürokratie. Das Protokoll – erhalten in einer einzigen Kopie – zeigt den Völkermord als Verwaltungsakt." },
  { id: "ge2-086", cat: "geschichte", topic: "NS-Diktatur", type: "number", emoji: "✡️", level: 1,
    value: "6 Mio.", label: "Im Holocaust ermordete Jüdinnen und Juden",
    text: "Rund zwei Drittel der europäischen Juden wurden ermordet – in Vernichtungslagern, durch Massenerschießungen, in Ghettos.",
    more: "Allein in Auschwitz-Birkenau starben rund 1,1 Mio. Menschen. Ermordet wurden auch Hunderttausende Sinti und Roma, Menschen mit Behinderung („Euthanasie“), sowjetische Kriegsgefangene, Homosexuelle und politische Gegner." },
  { id: "ge2-087", cat: "geschichte", topic: "NS-Diktatur", type: "truefalse", emoji: "🕯️", level: 1,
    q: "Das KZ Auschwitz wurde am 27. Januar 1945 von der Roten Armee befreit.",
    answer: true,
    explain: "Seit 1996 ist der 27. Januar in Deutschland Gedenktag für die Opfer des Nationalsozialismus, seit 2005 auch Internationaler Holocaust-Gedenktag der UN." },
  { id: "ge2-088", cat: "geschichte", topic: "NS-Diktatur", type: "truefalse", emoji: "🛣️", level: 3,
    q: "Hitler hat die Arbeitslosigkeit vor allem durch den Bau der Autobahnen beseitigt.",
    answer: false,
    explain: "Am Autobahnbau arbeiteten in der Spitze nur rund 120.000 Menschen. Entscheidend war die schuldenfinanzierte Aufrüstung (u. a. über Mefo-Wechsel), dazu Wehrpflicht und Arbeitsdienst. Die erste kreuzungsfreie Autobahn Köln–Bonn eröffnete übrigens 1932 Konrad Adenauer." },
  { id: "ge2-089", cat: "geschichte", topic: "NS-Diktatur", type: "flashcard", emoji: "🧾", level: 3,
    term: "Mefo-Wechsel",
    def: "Verdeckte Finanzierung der Aufrüstung ab 1934: Rüstungsfirmen erhielten Wechsel auf eine Scheinfirma (Metallurgische Forschungsgesellschaft), die die Reichsbank unter Hjalmar Schacht ankaufte.",
    example: "So tauchten Rüstungsschulden von rund 12 Mrd. Reichsmark nicht im Staatshaushalt auf – Geldschöpfung durch die Hintertür." },
  { id: "ge2-090", cat: "geschichte", topic: "NS-Diktatur", type: "event", emoji: "💼", level: 1, year: "1944",
    title: "20. Juli: Das Stauffenberg-Attentat",
    text: "Oberst Claus Schenk Graf von Stauffenberg deponiert im Führerhauptquartier „Wolfsschanze“ eine Bombe. Hitler überlebt leicht verletzt – ein schwerer Eichentisch dämpfte die Explosion.",
    more: "Der Umsturzplan „Walküre“ brach noch am selben Abend zusammen. Stauffenberg wurde in der Nacht erschossen, rund 200 Beteiligte später hingerichtet. Die Verschwörer wollten vor allem zeigen, dass es „ein anderes Deutschland“ gab." },
  { id: "ge2-091", cat: "geschichte", topic: "NS-Diktatur", type: "quiz", emoji: "🌹", level: 1,
    q: "Welche Widerstandsgruppe verteilte 1942/43 an der Münchner Universität Flugblätter?",
    options: ["Rote Kapelle", "Kreisauer Kreis", "Edelweißpiraten", "Weiße Rose"], answer: 3,
    explain: "Die Geschwister Hans und Sophie Scholl wurden beim Auslegen des sechsten Flugblatts im Lichthof der Uni ertappt und im Februar 1943 hingerichtet. Sophie Scholl war 21 Jahre alt." },
  { id: "ge2-092", cat: "geschichte", topic: "NS-Diktatur", type: "quiz", emoji: "💣", level: 2,
    q: "Wer verübte im November 1939 im Münchner Bürgerbräukeller allein ein Bombenattentat auf Hitler?",
    options: ["Claus von Stauffenberg", "Carl Goerdeler", "Georg Elser", "Helmuth James von Moltke"], answer: 2,
    explain: "Der Schreiner Georg Elser baute über Wochen nachts eine Bombe in eine Säule ein. Hitler verließ den Saal 13 Minuten vor der Explosion. Elser wurde im April 1945 im KZ Dachau ermordet – lange vergessen, heute als Held anerkannt." },
  { id: "ge2-093", cat: "geschichte", topic: "NS-Diktatur", type: "order", emoji: "⏳", level: 2,
    q: "Sortiere die Stufen der NS-Diktatur.",
    items: ["Ermächtigungsgesetz (1933)", "Nürnberger Gesetze (1935)", "Novemberpogrome (1938)", "Wannseekonferenz (1942)", "Attentat vom 20. Juli (1944)"],
    explain: "Von der Zerstörung der Demokratie über die rechtliche Ausgrenzung und offene Gewalt bis zum organisierten Völkermord – die Radikalisierung verlief schrittweise." },

  // ── Zweiter Weltkrieg ──
  { id: "ge2-094", cat: "geschichte", topic: "Zweiter Weltkrieg", type: "event", emoji: "🇵🇱", level: 1, year: "1939",
    title: "Überfall auf Polen",
    text: "Am 1. September 1939 greift Deutschland Polen an. Zwei Tage später erklären Großbritannien und Frankreich Deutschland den Krieg – der Zweite Weltkrieg beginnt.",
    more: "Vorbereitet durch den **Hitler-Stalin-Pakt** vom 23. August 1939: Im geheimen Zusatzprotokoll teilten die beiden Diktatoren Osteuropa auf. Am 17. September marschierte die Rote Armee in Ostpolen ein. Den Vorwand lieferte ein inszenierter „polnischer“ Überfall auf den Sender Gleiwitz." },
  { id: "ge2-095", cat: "geschichte", topic: "Zweiter Weltkrieg", type: "quiz", emoji: "🤝", level: 2,
    q: "Was regelte das geheime Zusatzprotokoll des Hitler-Stalin-Pakts?",
    options: ["Einen gemeinsamen Angriff auf Großbritannien", "Die Aufteilung Osteuropas in Interessensphären", "Den Austausch von Atomforschung", "Ein Bündnis gegen Japan"], answer: 1,
    explain: "Ostpolen, die baltischen Staaten, Finnland und Bessarabien wurden der sowjetischen Sphäre zugeschlagen. Die Sowjetunion leugnete die Existenz des Protokolls bis 1989." },
  { id: "ge2-096", cat: "geschichte", topic: "Zweiter Weltkrieg", type: "truefalse", emoji: "✈️", level: 2,
    q: "In der Luftschlacht um England 1940 erlitt Hitler seinen ersten großen Rückschlag.",
    answer: true,
    explain: "Die Luftwaffe erreichte keine Luftüberlegenheit, die geplante Invasion („Unternehmen Seelöwe“) wurde abgesagt. Churchill: „Nie zuvor haben so viele so wenigen so viel zu verdanken gehabt.“" },
  { id: "ge2-097", cat: "geschichte", topic: "Zweiter Weltkrieg", type: "event", emoji: "❄️", level: 1, year: "1941",
    title: "Unternehmen Barbarossa",
    text: "Am 22. Juni 1941 überfällt Deutschland mit über 3 Mio. Soldaten die Sowjetunion – unter Bruch des Nichtangriffspakts. Der Krieg im Osten wird als rassistischer Vernichtungskrieg geführt.",
    more: "Im Dezember 1941 stoppte die Rote Armee die Wehrmacht vor Moskau. Im selben Monat erklärte Hitler nach Pearl Harbor (7. Dezember) den USA den Krieg – damit kämpfte Deutschland gegen die drei größten Mächte der Welt zugleich." },
  { id: "ge2-098", cat: "geschichte", topic: "Zweiter Weltkrieg", type: "event", emoji: "🏚️", level: 1, year: "1943",
    title: "Stalingrad: Die Wende im Osten",
    text: "Anfang Februar 1943 kapituliert die eingekesselte 6. Armee in Stalingrad. Von rund 91.000 deutschen Kriegsgefangenen kehrten nur etwa 6.000 nach Hause zurück.",
    more: "Stalingrad gilt als psychologischer Wendepunkt: Danach glaubten viele Deutsche nicht mehr an den „Endsieg“. Goebbels antwortete mit der Sportpalastrede: „Wollt ihr den totalen Krieg?“ Im Sommer 1943 folgte mit der Panzerschlacht bei Kursk die endgültige militärische Wende im Osten." },
  { id: "ge2-099", cat: "geschichte", topic: "Zweiter Weltkrieg", type: "quiz", emoji: "🌊", level: 3,
    q: "Welche Schlacht gilt als Wendepunkt des Krieges im Pazifik?",
    options: ["Pearl Harbor (1941)", "Iwo Jima (1945)", "Okinawa (1945)", "Midway (1942)"], answer: 3,
    explain: "Im Juni 1942 versenkten die USA bei Midway vier japanische Flugzeugträger. Möglich wurde das, weil US-Kryptologen den japanischen Funkcode geknackt hatten. Danach war Japan in der Defensive." },
  { id: "ge2-100", cat: "geschichte", topic: "Zweiter Weltkrieg", type: "event", emoji: "🏖️", level: 1, year: "1944",
    title: "D-Day: Landung in der Normandie",
    text: "Am 6. Juni 1944 landen alliierte Truppen unter US-General Eisenhower an fünf Strandabschnitten der Normandie – die größte Landungsoperation der Geschichte. Die zweite Front ist eröffnet.",
    more: "Ein Täuschungsmanöver („Operation Fortitude“ mit Gummipanzern und Funkverkehr) ließ die Deutschen die Landung bei Calais erwarten. Ende August 1944 war Paris befreit." },
  { id: "ge2-101", cat: "geschichte", topic: "Zweiter Weltkrieg", type: "event", emoji: "🏳️", level: 1, year: "1945",
    title: "Bedingungslose Kapitulation",
    text: "Am 8. Mai 1945 tritt die bedingungslose Kapitulation der Wehrmacht in Kraft. Hitler hatte sich am 30. April im Berliner Führerbunker das Leben genommen. Der Krieg in Europa ist vorbei.",
    more: "In Moskau war es wegen der Zeitverschiebung bereits der 9. Mai – deshalb feiert Russland den „Tag des Sieges“ einen Tag später. Bundespräsident Richard von Weizsäcker nannte den 8. Mai 1985 einen „Tag der Befreiung“." },
  { id: "ge2-102", cat: "geschichte", topic: "Zweiter Weltkrieg", type: "event", emoji: "☢️", level: 1, year: "1945",
    title: "Atombomben auf Hiroshima und Nagasaki",
    text: "Am 6. und 9. August 1945 werfen die USA Atombomben auf Hiroshima und Nagasaki. Bis Ende 1945 sterben über 200.000 Menschen. Japan kapituliert; am 2. September endet der Zweite Weltkrieg.",
    more: "Bis heute die einzigen Atomwaffeneinsätze im Krieg. Die Bombe machte die USA kurzzeitig zur einzigen Atommacht – 1949 zog die Sowjetunion nach. Das „Gleichgewicht des Schreckens“ prägte den gesamten Kalten Krieg." },
  { id: "ge2-103", cat: "geschichte", topic: "Zweiter Weltkrieg", type: "number", emoji: "⚰️", level: 1,
    value: "60 Mio.+", label: "Tote im Zweiten Weltkrieg",
    text: "Der verheerendste Konflikt der Geschichte – mehr als die Hälfte der Opfer waren Zivilisten.",
    more: "Die Sowjetunion verlor rund 27 Mio. Menschen, China zwischen 15 und 20 Mio., Polen etwa 6 Mio. (rund 17 % der Bevölkerung), Deutschland rund 6–7 Mio. Diese Erfahrung ist Grundlage der UN (1945) und der europäischen Einigung." },
  { id: "ge2-104", cat: "geschichte", topic: "Zweiter Weltkrieg", type: "order", emoji: "⏳", level: 1,
    q: "Sortiere die Wendepunkte des Zweiten Weltkriegs.",
    items: ["Überfall auf Polen (1939)", "Angriff auf die Sowjetunion (1941)", "Kapitulation in Stalingrad (1943)", "D-Day (1944)", "Kriegsende in Europa (1945)"],
    explain: "Bis 1941 Blitzkriege, ab 1941 Weltkrieg mit USA und UdSSR, ab 1943 Rückzug an allen Fronten." },

  // ── Nachkriegszeit ──
  { id: "ge2-105", cat: "geschichte", topic: "Nachkriegszeit", type: "event", emoji: "🤝", level: 1, year: "1945",
    title: "Potsdamer Konferenz",
    text: "Vom 17. Juli bis 2. August 1945 legen Truman, Stalin und Churchill (ab Ende Juli sein Nachfolger Attlee) die Grundsätze für Deutschland fest: Entmilitarisierung, Entnazifizierung, Dezentralisierung, Demokratisierung.",
    more: "Merkhilfe: die „4 D“ (oft ergänzt um Demontage als fünftes D). Die Gebiete östlich von Oder und Neiße kamen unter polnische bzw. sowjetische Verwaltung; Millionen Deutsche wurden vertrieben. Über eine gemeinsame Deutschlandpolitik konnten sich die Sieger bald nicht mehr einigen." },
  { id: "ge2-106", cat: "geschichte", topic: "Nachkriegszeit", type: "event", emoji: "⚖️", level: 3, year: "1945",
    title: "Nürnberger Prozess gegen die Hauptkriegsverbrecher",
    text: "Vom 20. November 1945 bis 1. Oktober 1946 stehen führende NS-Funktionäre vor einem internationalen Militärgericht. Es ergehen 12 Todesurteile, u. a. gegen Göring, Ribbentrop und Keitel.",
    more: "Neu war der Grundsatz, dass Staatsführer persönlich für Angriffskrieg und „Verbrechen gegen die Menschlichkeit“ haften. Der Prozess gilt als Geburtsstunde des Völkerstrafrechts – bis zum Internationalen Strafgerichtshof in Den Haag (2002). Göring entzog sich der Hinrichtung durch Suizid." },
  { id: "ge2-107", cat: "geschichte", topic: "Nachkriegszeit", type: "event", emoji: "🇺🇸", level: 1, year: "1947",
    title: "Der Marshallplan wird angekündigt",
    text: "Am 5. Juni 1947 kündigt US-Außenminister George Marshall in Harvard ein Wiederaufbauprogramm für Europa an. Bis 1952 fließen rund 13 Mrd. US-Dollar, davon rund 1,4 Mrd. nach Westdeutschland.",
    more: "Ziel war auch, Westeuropa gegen den Kommunismus zu stabilisieren – die Sowjetunion verbot ihren Satelliten die Teilnahme. Bleibendes Erbe: Zur Verwaltung der Gelder wurde 1948 die KfW gegründet; das ERP-Sondervermögen fördert bis heute Mittelständler und Gründer." },
  { id: "ge2-108", cat: "geschichte", topic: "Nachkriegszeit", type: "event", emoji: "💶", level: 1, year: "1948",
    title: "Währungsreform: Die D-Mark kommt",
    text: "Am 20. Juni 1948 wird in den Westzonen die Deutsche Mark eingeführt. Jeder erhält zunächst 40 DM „Kopfgeld“. Fast über Nacht füllen sich die Schaufenster.",
    more: "Die Händler hatten Waren gehortet, weil die Reichsmark wertlos war (Ersatzwährung: Zigaretten). Ludwig Erhard hob zeitgleich – gegen den Willen der Alliierten – die meisten Preiskontrollen auf. Geldreform plus Marktfreiheit: Startschuss des Wirtschaftswunders." },
  { id: "ge2-109", cat: "geschichte", topic: "Nachkriegszeit", type: "quiz", emoji: "💵", level: 2,
    q: "Wie viel „Kopfgeld“ in D-Mark erhielt jeder Westdeutsche am 20. Juni 1948 zunächst?",
    options: ["100 DM", "60 DM", "40 DM", "20 DM"], answer: 2,
    explain: "40 DM sofort, weitere 20 DM einige Wochen später. Reichsmark-Guthaben wurden im Ergebnis auf 6,5 % abgewertet – Sparer verloren erneut, Besitzer von Sachwerten gewannen." },
  { id: "ge2-110", cat: "geschichte", topic: "Nachkriegszeit", type: "event", emoji: "✈️", level: 1, year: "1948",
    title: "Berlin-Blockade und Luftbrücke",
    text: "Vom 24. Juni 1948 bis 12. Mai 1949 sperrt die Sowjetunion alle Land- und Wasserwege nach West-Berlin. Die Westalliierten versorgen die Stadt fast ein Jahr lang aus der Luft.",
    more: "Rund 2,3 Mio. Tonnen Güter, vor allem Kohle und Lebensmittel; zeitweise landete alle paar Minuten ein Flugzeug in Tempelhof. Die „Rosinenbomber“ machten aus Besatzern Beschützer – ein Schlüsselmoment der Westbindung." },
  { id: "ge2-111", cat: "geschichte", topic: "Nachkriegszeit", type: "whatif", emoji: "🔗", level: 3,
    q: "Was folgte aus der Währungsreform in den Westzonen 1948?",
    steps: ["Sowjets befürchten Währungschaos im Osten", "Blockade West-Berlins ab Juni 1948", "Westalliierte antworten mit Luftbrücke", "Spaltung vertieft sich", "1949: zwei deutsche Staaten"],
    text: "Die Währungsreform war ein Wirtschafts- und zugleich ein Teilungsakt. Die Sowjetunion führte eine eigene Ostmark ein und versuchte, die Westmächte aus Berlin zu drängen. Am Ende stand die doppelte Staatsgründung." },
  { id: "ge2-112", cat: "geschichte", topic: "Nachkriegszeit", type: "event", emoji: "📘", level: 1, year: "1949",
    title: "Zwei deutsche Staaten entstehen",
    text: "Am 23. Mai 1949 wird das Grundgesetz verkündet – die Bundesrepublik ist gegründet. Am 7. Oktober 1949 folgt in Ost-Berlin die Gründung der DDR.",
    more: "Das Grundgesetz war als Provisorium gedacht – daher „Grundgesetz“ statt „Verfassung“. Es wurde vom Parlamentarischen Rat unter Vorsitz Konrad Adenauers erarbeitet. Erst mit der Wiedervereinigung 1990 wurde es zur gesamtdeutschen Verfassung." },
  { id: "ge2-113", cat: "geschichte", topic: "Nachkriegszeit", type: "truefalse", emoji: "🏙️", level: 2,
    q: "Bonn wurde 1949 Hauptstadt, weil es die größte Stadt der Westzonen war.",
    answer: false,
    explain: "Bonn war bewusst klein – das unterstrich den provisorischen Charakter bis zur Wiedervereinigung. Frankfurt hätte wie eine Dauerlösung gewirkt. Dass Adenauer im nahen Rhöndorf wohnte, schadete auch nicht." },
  { id: "ge2-114", cat: "geschichte", topic: "Nachkriegszeit", type: "order", emoji: "⏳", level: 2,
    q: "Sortiere den Weg zur doppelten Staatsgründung.",
    items: ["Potsdamer Konferenz (1945)", "Ankündigung des Marshallplans (1947)", "Währungsreform (Juni 1948)", "Grundgesetz (Mai 1949)", "Gründung der DDR (Oktober 1949)"],
    explain: "Wirtschaftliche Weichenstellungen (Marshallplan, D-Mark) gingen der politischen Teilung voraus." },

  // ── Wirtschaftswunder ──
  { id: "ge2-115", cat: "geschichte", topic: "Wirtschaftswunder", type: "fact", emoji: "⚖️", level: 2,
    title: "Soziale Marktwirtschaft: Markt plus Ausgleich",
    text: "Der Begriff stammt von Alfred **Müller-Armack**, politisch umgesetzt hat ihn Ludwig **Erhard**. Idee: freie Preise und Wettbewerb, aber ein starker Staat, der Kartelle verhindert und sozialen Ausgleich schafft.",
    more: "Wurzel ist der Ordoliberalismus der „Freiburger Schule“ (Walter Eucken): Der Staat setzt die Spielregeln, spielt aber nicht selbst mit. Erbe: das Kartellgesetz von 1957 und das Bundeskartellamt. Bis heute Leitbild deutscher Wirtschaftspolitik." },
  { id: "ge2-116", cat: "geschichte", topic: "Wirtschaftswunder", type: "quiz", emoji: "📗", level: 1,
    q: "Wer schrieb 1957 das Buch „Wohlstand für Alle“?",
    options: ["Konrad Adenauer", "Alfred Müller-Armack", "Karl Schiller", "Ludwig Erhard"], answer: 3,
    explain: "Erhard war 1949–1963 Wirtschaftsminister und danach bis 1966 Kanzler. Sein Markenzeichen: die Zigarre und der Slogan vom Wohlstand für alle, nicht für wenige." },
  { id: "ge2-117", cat: "geschichte", topic: "Wirtschaftswunder", type: "event", emoji: "⚽", level: 1, year: "1954",
    title: "Das Wunder von Bern",
    text: "Am 4. Juli 1954 schlägt die Bundesrepublik im WM-Finale in Bern den haushohen Favoriten Ungarn mit 3:2. Radiokommentator Herbert Zimmermann: „Aus! Aus! Das Spiel ist aus!“",
    more: "Für viele Historiker der eigentliche emotionale Gründungsmoment der Bundesrepublik: „Wir sind wieder wer.“ Die Ungarn hatten Deutschland in der Vorrunde noch 8:3 besiegt." },
  { id: "ge2-118", cat: "geschichte", topic: "Wirtschaftswunder", type: "number", emoji: "🛵", level: 2,
    value: "1.000.000", label: "Gastarbeiter Nr. 1 Million kam 1964 nach Köln",
    text: "Der Portugiese Armando Rodrigues de Sá wurde am Bahnhof Köln-Deutz begrüßt – und bekam als Geschenk ein Moped.",
    more: "Das Wirtschaftswunder führte zur Vollbeschäftigung; die Bundesrepublik schloss Anwerbeabkommen: Italien 1955, Spanien und Griechenland 1960, Türkei 1961, Portugal 1964. Gedacht war ein „Rotationsprinzip“ – doch viele blieben, holten Familien nach und prägten das Land." },
  { id: "ge2-119", cat: "geschichte", topic: "Wirtschaftswunder", type: "truefalse", emoji: "📉", level: 3,
    q: "Die erste Rezession der Bundesrepublik kam erst 1966/67.",
    answer: true,
    explain: "Das BIP schrumpfte 1967 leicht. Kanzler Erhard stürzte, die erste Große Koalition übernahm. Wirtschaftsminister Karl Schiller setzte mit dem Stabilitätsgesetz 1967 auf keynesianische Globalsteuerung – das „magische Viereck“ stammt daher." },

  // ── Kalter Krieg ──
  { id: "ge2-120", cat: "geschichte", topic: "Kalter Krieg", type: "fact", emoji: "🧱", level: 1,
    title: "Der „Eiserne Vorhang“",
    text: "Am 5. März 1946 sagt Winston Churchill in Fulton (USA): „Von Stettin an der Ostsee bis Triest an der Adria hat sich ein eiserner Vorhang über den Kontinent gesenkt.“",
    more: "Die Rede gilt als eine der Geburtsurkunden des Kalten Krieges. 1947 folgte die **Truman-Doktrin**: Die USA wollten die Ausbreitung des Kommunismus weltweit eindämmen („Containment“). Der Marshallplan war ihre wirtschaftliche Seite." },
  { id: "ge2-121", cat: "geschichte", topic: "Kalter Krieg", type: "event", emoji: "🛡️", level: 1, year: "1949",
    title: "Gründung der NATO",
    text: "Am 4. April 1949 gründen zwölf Staaten in Washington das Nordatlantische Verteidigungsbündnis. Kern ist Artikel 5: Ein Angriff auf einen gilt als Angriff auf alle.",
    more: "Erster NATO-Generalsekretär Lord Ismay fasste den Zweck spöttisch zusammen: „Die Amerikaner drin, die Russen draußen und die Deutschen unten halten.“ Die Bundesrepublik trat 1955 bei – die Sowjetunion antwortete wenige Tage später mit dem Warschauer Pakt." },
  { id: "ge2-122", cat: "geschichte", topic: "Kalter Krieg", type: "quiz", emoji: "🎖️", level: 2,
    q: "In welchem Jahr trat die Bundesrepublik der NATO bei?",
    options: ["1949", "1955", "1961", "1990"], answer: 1,
    explain: "Mit dem Beitritt am 9. Mai 1955 (Pariser Verträge) wurde die Bundesrepublik weitgehend souverän und baute die Bundeswehr auf. Der Warschauer Pakt folgte am 14. Mai 1955; die DDR gründete 1956 die Nationale Volksarmee." },
  { id: "ge2-123", cat: "geschichte", topic: "Kalter Krieg", type: "event", emoji: "🇰🇷", level: 2, year: "1950",
    title: "Koreakrieg: Der Kalte Krieg wird heiß",
    text: "Im Juni 1950 überfällt Nordkorea den Süden. Eine UN-Truppe unter US-Führung greift ein, China unterstützt den Norden. 1953 endet der Krieg mit einem Waffenstillstand nahe dem 38. Breitengrad.",
    more: "Einen Friedensvertrag gibt es bis heute nicht. Wirtschaftliche Nebenwirkung: Der „Korea-Boom“ – weltweite Nachfrage nach Industriegütern – kurbelte die westdeutschen Exporte kräftig an und beschleunigte das Wirtschaftswunder." },
  { id: "ge2-124", cat: "geschichte", topic: "Kalter Krieg", type: "event", emoji: "✊", level: 1, year: "1953",
    title: "Volksaufstand vom 17. Juni in der DDR",
    text: "Was als Protest Ost-Berliner Bauarbeiter gegen erhöhte Arbeitsnormen beginnt, wird zum landesweiten Aufstand für freie Wahlen. Sowjetische Panzer schlagen ihn nieder; Dutzende Menschen sterben.",
    more: "Der 17. Juni war bis 1990 in der Bundesrepublik Nationalfeiertag („Tag der deutschen Einheit“). Ähnlich endeten der Ungarnaufstand 1956 und der Prager Frühling 1968 – der Westen griff jeweils nicht militärisch ein." },
  { id: "ge2-125", cat: "geschichte", topic: "Kalter Krieg", type: "event", emoji: "🧱", level: 1, year: "1961",
    title: "Bau der Berliner Mauer",
    text: "In der Nacht zum 13. August 1961 riegelt die DDR die Sektorengrenze in Berlin ab. Zwei Monate zuvor hatte Walter Ulbricht erklärt: „Niemand hat die Absicht, eine Mauer zu errichten.“",
    more: "Die DDR nannte sie „antifaschistischen Schutzwall“ – tatsächlich sollte sie die Massenflucht stoppen, die das Land ausblutete. Bis 1989 starben an der Berliner Mauer mindestens 140 Menschen." },
  { id: "ge2-126", cat: "geschichte", topic: "Kalter Krieg", type: "number", emoji: "🚶", level: 3,
    value: "≈ 2,7 Mio.", label: "Menschen flohen 1949 bis August 1961 aus der DDR",
    text: "Viele davon jung und gut ausgebildet: Ärzte, Ingenieure, Facharbeiter.",
    more: "Diese „Abstimmung mit den Füßen“ bedrohte die DDR-Wirtschaft existenziell. Ökonomisch gesprochen: ein massiver Verlust an Humankapital. Der Mauerbau war damit vor allem eine wirtschaftliche Notbremse – mit brutalen menschlichen Folgen." },
  { id: "ge2-127", cat: "geschichte", topic: "Kalter Krieg", type: "event", emoji: "🚀", level: 1, year: "1962",
    title: "Kubakrise: 13 Tage am Abgrund",
    text: "Im Oktober 1962 entdecken US-Aufklärer sowjetische Atomraketen auf Kuba. Kennedy verhängt eine Seeblockade. Nach 13 Tagen lenkt Chruschtschow ein und zieht die Raketen ab.",
    more: "Gegenleistung: Die USA garantierten, Kuba nicht anzugreifen, und zogen – geheim vereinbart – ihre Jupiter-Raketen aus der Türkei ab. Die Welt war einem Atomkrieg nie näher." },
  { id: "ge2-128", cat: "geschichte", topic: "Kalter Krieg", type: "whatif", emoji: "☎️", level: 2,
    q: "Was folgte aus der Kubakrise 1962?",
    steps: ["Beide Seiten erkennen das Risiko eines Atomkriegs", "1963: „Heißer Draht“ Washington–Moskau", "1963: Vertrag über begrenzten Atomteststopp", "Beginn der Entspannungspolitik"],
    text: "Die Krise wurde zum Lernmoment. Die direkte Fernschreibverbindung sollte Missverständnisse verhindern. Später folgten der Atomwaffensperrvertrag (1968) und Rüstungskontrollverträge wie SALT I (1972)." },
  { id: "ge2-129", cat: "geschichte", topic: "Kalter Krieg", type: "quiz", emoji: "🎤", level: 1,
    q: "In welchem Jahr rief John F. Kennedy in West-Berlin „Ich bin ein Berliner“?",
    options: ["1961", "1963", "1962", "1968"], answer: 1,
    explain: "Am 26. Juni 1963 vor dem Schöneberger Rathaus. Der Mythos, er habe sich als „Krapfen“ bezeichnet, ist falsch – „ein Berliner“ war grammatisch korrekt und wurde genau so verstanden." },
  { id: "ge2-130", cat: "geschichte", topic: "Kalter Krieg", type: "event", emoji: "🪖", level: 2, year: "1965",
    title: "Vietnamkrieg: Die USA steigen massiv ein",
    text: "Nach dem Tonkin-Zwischenfall 1964 schicken die USA ab 1965 Kampftruppen – bis zu über 500.000 Soldaten. Die Tet-Offensive 1968 zeigt, dass der Krieg nicht zu gewinnen ist.",
    more: "1973 zogen die USA ab, im April 1975 fiel Saigon an Nordvietnam. Der Krieg befeuerte weltweit Proteste, auch die westdeutsche Studentenbewegung. In den USA bewirkte er ein tiefes Misstrauen gegenüber der Regierung." },
  { id: "ge2-131", cat: "geschichte", topic: "Kalter Krieg", type: "fact", emoji: "✊", level: 2,
    title: "1968: Revolte im Westen, Panzer im Osten",
    text: "In Westdeutschland protestieren Studenten gegen Vietnamkrieg, Notstandsgesetze und das Schweigen der Elterngeneration über die NS-Zeit. Im Osten beenden am 21. August 1968 Truppen des Warschauer Pakts den „Prager Frühling“.",
    more: "Auslöser der Radikalisierung war der Tod des Studenten Benno Ohnesorg bei einer Demo 1967 und das Attentat auf Rudi Dutschke im April 1968. Folgen: gesellschaftliche Liberalisierung, Frauenbewegung, Umweltbewegung – aber auch die RAF." },
  { id: "ge2-132", cat: "geschichte", topic: "Kalter Krieg", type: "truefalse", emoji: "✈️", level: 2,
    q: "Im „Deutschen Herbst“ 1977 befreite die GSG 9 in Mogadischu die entführte Lufthansa-Maschine „Landshut“.",
    answer: true,
    explain: "Am 18. Oktober 1977 wurden alle 86 Passagiere befreit. Die RAF hatte zuvor Arbeitgeberpräsident Hanns Martin Schleyer entführt; nach dem Scheitern ihrer Erpressung wurde er ermordet. Kanzler Schmidt war hart geblieben." },

  // ── Wettlauf ins All ──
  { id: "ge2-133", cat: "geschichte", topic: "Wettlauf ins All", type: "event", emoji: "🛰️", level: 2, year: "1957",
    title: "Sputnik-Schock",
    text: "Am 4. Oktober 1957 schießt die Sowjetunion den ersten künstlichen Satelliten ins All. Sein Piepsen ist weltweit per Funk zu empfangen – und versetzt den Westen in Panik.",
    more: "Wer Satelliten starten kann, kann auch Atomraketen nach Amerika schießen. Die USA gründeten 1958 die NASA und investierten massiv in Bildung und Forschung – auch die Vorläuferbehörde, aus der später das Internet (ARPANET) hervorging, entstand 1958 als Reaktion." },
  { id: "ge2-134", cat: "geschichte", topic: "Wettlauf ins All", type: "quiz", emoji: "👨‍🚀", level: 1,
    q: "Wer war 1961 der erste Mensch im Weltraum?",
    options: ["Neil Armstrong", "John Glenn", "Juri Gagarin", "Alan Shepard"], answer: 2,
    explain: "Am 12. April 1961 umrundete Gagarin in 108 Minuten einmal die Erde. Ein weiterer Triumph für Moskau – woraufhin Kennedy im Mai 1961 das Ziel ausgab, noch im Jahrzehnt einen Menschen auf den Mond zu bringen." },
  { id: "ge2-135", cat: "geschichte", topic: "Wettlauf ins All", type: "event", emoji: "🌕", level: 1, year: "1969",
    title: "Apollo 11: Menschen auf dem Mond",
    text: "Am 20. Juli 1969 landet die Mondfähre „Eagle“. Neil Armstrong betritt als erster Mensch den Mond: „Ein kleiner Schritt für einen Menschen, ein riesiger Sprung für die Menschheit.“",
    more: "Rund 600 Mio. Menschen sahen live zu. Der Bordcomputer hatte weniger Rechenleistung als heute ein Taschenrechner. Bis 1972 betraten insgesamt zwölf Menschen – alle US-Amerikaner – den Mond. Kennedys Ziel war erreicht, der Wettlauf entschieden." },
  { id: "ge2-136", cat: "geschichte", topic: "Wettlauf ins All", type: "truefalse", emoji: "🚀", level: 1,
    q: "Bei Apollo 11 betraten alle drei Astronauten den Mond.",
    answer: false,
    explain: "Nur Neil Armstrong und Buzz Aldrin stiegen aus. Michael Collins kreiste allein im Kommandomodul um den Mond – auf der Rückseite ohne jeden Funkkontakt zur Erde." },

  // ── Ostpolitik ──
  { id: "ge2-137", cat: "geschichte", topic: "Ostpolitik", type: "event", emoji: "🙏", level: 1, year: "1970",
    title: "Brandts Kniefall in Warschau",
    text: "Am 7. Dezember 1970 kniet Bundeskanzler Willy Brandt vor dem Ehrenmal für die Opfer des Warschauer Ghettoaufstands nieder – eine spontane Geste der Demut.",
    more: "Am selben Tag unterzeichnete er den Warschauer Vertrag, der die Oder-Neiße-Grenze faktisch anerkannte. In der Bundesrepublik war die Geste damals umstritten. 1971 erhielt Brandt den Friedensnobelpreis." },
  { id: "ge2-138", cat: "geschichte", topic: "Ostpolitik", type: "flashcard", emoji: "🌉", level: 3,
    term: "Wandel durch Annäherung",
    def: "Formel von Egon Bahr (1963): Statt die DDR und den Ostblock zu isolieren, sollte man durch Verträge und Kontakte schrittweise Veränderungen ermöglichen.",
    example: "Grundlage der Ostverträge (Moskau und Warschau 1970), des Grundlagenvertrags mit der DDR (1972) und von Reiseerleichterungen." },
  { id: "ge2-139", cat: "geschichte", topic: "Ostpolitik", type: "event", emoji: "📜", level: 3, year: "1975",
    title: "KSZE-Schlussakte von Helsinki",
    text: "35 Staaten aus Ost und West, darunter beide deutsche Staaten, unterzeichnen am 1. August 1975 die Schlussakte: Unverletzlichkeit der Grenzen – aber auch Achtung der Menschenrechte.",
    more: "Moskau wollte die Anerkennung der Nachkriegsgrenzen. Doch der Menschenrechtsteil wurde zur Zeitbombe: Bürgerrechtler wie die Charta 77 (ČSSR) oder Ausreisewillige in der DDR beriefen sich darauf. Aus der KSZE wurde später die OSZE." },
  { id: "ge2-140", cat: "geschichte", topic: "Ostpolitik", type: "event", emoji: "🚀", level: 3, year: "1979",
    title: "NATO-Doppelbeschluss",
    text: "Im Dezember 1979 bietet die NATO der Sowjetunion Verhandlungen über deren neue SS-20-Raketen an – und droht für den Fall des Scheiterns mit der Stationierung von Pershing-II-Raketen und Marschflugkörpern.",
    more: "Angeregt hatte ihn Kanzler Helmut Schmidt. Hunderttausende demonstrierten in der Friedensbewegung; der Streit spaltete die SPD und trug 1982 zu Schmidts Sturz bei. 1983 stationierte der Bundestag unter Kohl. 1987 schafften USA und UdSSR im INF-Vertrag alle Mittelstreckenraketen ab." },
  { id: "ge2-141", cat: "geschichte", topic: "Kalter Krieg", type: "order", emoji: "⏳", level: 1,
    q: "Sortiere die Etappen des Kalten Krieges.",
    items: ["NATO-Gründung (1949)", "Mauerbau (1961)", "Kubakrise (1962)", "Mondlandung (1969)", "KSZE-Schlussakte (1975)"],
    explain: "Merke: Auf die Konfrontation der 1950er/60er folgte nach der Kubakrise die Entspannungsphase der 1970er." },

  // ── Europäische Integration ──
  { id: "ge2-142", cat: "geschichte", topic: "Europäische Einigung", type: "event", emoji: "🇪🇺", level: 2, year: "1950",
    title: "Schuman-Erklärung",
    text: "Am 9. Mai 1950 schlägt Frankreichs Außenminister Robert Schuman vor, die gesamte deutsch-französische Kohle- und Stahlproduktion einer gemeinsamen Behörde zu unterstellen. Ein Krieg solle so „materiell unmöglich“ werden.",
    more: "Der Plan stammte von Jean Monnet. Der 9. Mai wird heute als Europatag gefeiert. Die Methode „Schritt für Schritt über die Wirtschaft zur politischen Einheit“ prägt die EU bis heute." },
  { id: "ge2-143", cat: "geschichte", topic: "Europäische Einigung", type: "event", emoji: "⚒️", level: 1, year: "1951",
    title: "Die Montanunion wird gegründet",
    text: "Am 18. April 1951 unterzeichnen Frankreich, die Bundesrepublik, Italien, Belgien, die Niederlande und Luxemburg in Paris den Vertrag über die Europäische Gemeinschaft für Kohle und Stahl (EGKS).",
    more: "Warum ausgerechnet Kohle und Stahl? Sie waren die Rohstoffe der Rüstung. Wer sie gemeinsam kontrolliert, kann nicht heimlich aufrüsten. Für die junge Bundesrepublik war die EGKS zugleich ein Weg zurück in die Gemeinschaft der Staaten." },
  { id: "ge2-144", cat: "geschichte", topic: "Europäische Einigung", type: "event", emoji: "🏛️", level: 1, year: "1957",
    title: "Römische Verträge: Die EWG entsteht",
    text: "Am 25. März 1957 gründen die sechs Montanunion-Staaten in Rom die Europäische Wirtschaftsgemeinschaft (EWG) und Euratom. Ziel: ein gemeinsamer Markt mit Zollunion.",
    more: "Die Zollunion war schon 1968 vollendet – früher als geplant. Die EWG ist der direkte Vorläufer der EU; der „Vertrag über die Arbeitsweise der EU“ geht bis heute auf den EWG-Vertrag zurück." },
  { id: "ge2-145", cat: "geschichte", topic: "Europäische Einigung", type: "quiz", emoji: "🗺️", level: 1,
    q: "Welches Land gehörte NICHT zu den sechs Gründungsstaaten der EWG?",
    options: ["Belgien", "Luxemburg", "Großbritannien", "Italien"], answer: 2,
    explain: "Großbritannien setzte zunächst auf die Freihandelszone EFTA. Beitrittsgesuche 1963 und 1967 scheiterten am Veto von Charles de Gaulle; erst 1973 trat es zusammen mit Irland und Dänemark bei." },
  { id: "ge2-146", cat: "geschichte", topic: "Europäische Einigung", type: "event", emoji: "🇫🇷", level: 3, year: "1963",
    title: "Élysée-Vertrag: Aus Erbfeinden werden Partner",
    text: "Am 22. Januar 1963 besiegeln Konrad Adenauer und Charles de Gaulle die deutsch-französische Freundschaft: regelmäßige Regierungskonsultationen und Jugendaustausch.",
    more: "Das Deutsch-Französische Jugendwerk hat seither Millionen junge Menschen zusammengebracht. Nach drei Kriegen in 70 Jahren (1870, 1914, 1939) wurde die Achse Paris–Berlin zum Motor der europäischen Einigung." },
  { id: "ge2-147", cat: "geschichte", topic: "Europäische Einigung", type: "event", emoji: "🖊️", level: 1, year: "1992",
    title: "Vertrag von Maastricht: Die EU entsteht",
    text: "Am 7. Februar 1992 unterzeichnen zwölf Staaten in Maastricht den Vertrag über die Europäische Union. Er beschließt die Wirtschafts- und Währungsunion samt gemeinsamer Währung.",
    more: "Dazu kamen eine gemeinsame Außen- und Sicherheitspolitik, Zusammenarbeit in Justiz und Innerem und die Unionsbürgerschaft. Frankreich wollte die D-Mark-Dominanz der Bundesbank brechen; Deutschland setzte im Gegenzug strenge Stabilitätsregeln durch." },
  { id: "ge2-148", cat: "geschichte", topic: "Europäische Einigung", type: "flashcard", emoji: "📏", level: 3,
    term: "Maastricht-Kriterien",
    def: "Bedingungen für die Euro-Einführung: Haushaltsdefizit max. 3 % und Staatsschulden max. 60 % des BIP, niedrige Inflation und Zinsen, stabiler Wechselkurs.",
    example: "Griechenland trat 2001 dem Euro bei – später kam heraus, dass die Defizitzahlen geschönt waren. Ein Vorspiel zur Eurokrise." },
  { id: "ge2-149", cat: "geschichte", topic: "Europäische Einigung", type: "event", emoji: "💶", level: 1, year: "2002",
    title: "Euro-Bargeld kommt in die Taschen",
    text: "Der Euro startete am 1. Januar 1999 als Buchgeld in elf Staaten. Am 1. Januar 2002 folgten Scheine und Münzen in zwölf Ländern – die größte Bargeldumstellung der Geschichte.",
    more: "Der Wechselkurs zur D-Mark wurde unwiderruflich festgelegt. Das Gefühl vom „Teuro“ hielt sich hartnäckig, obwohl die gemessene Inflation kaum stieg – vor allem häufig gekaufte Dinge wie Restaurantbesuche wurden teurer und prägten die Wahrnehmung." },
  { id: "ge2-150", cat: "geschichte", topic: "Europäische Einigung", type: "number", emoji: "🔢", level: 1,
    value: "1,95583", label: "D-Mark für einen Euro – der feste Umrechnungskurs",
    text: "Viele rechneten jahrelang im Kopf grob „mal zwei“, um Euro-Preise in D-Mark zu übersetzen.",
    more: "D-Mark-Bargeld kann bis heute unbefristet und gebührenfrei bei der Bundesbank umgetauscht werden. Schätzungen zufolge sind noch Milliarden D-Mark in Schubladen und Sparschweinen unterwegs." },
  { id: "ge2-151", cat: "geschichte", topic: "Europäische Einigung", type: "event", emoji: "🤝", level: 2, year: "2004",
    title: "EU-Osterweiterung",
    text: "Am 1. Mai 2004 treten zehn Staaten bei, darunter Polen, Tschechien, Ungarn und die drei baltischen Staaten. Die EU wächst auf 25 Mitglieder – die größte Erweiterung ihrer Geschichte.",
    more: "15 Jahre nach dem Fall des Eisernen Vorhangs wurde der Kontinent wieder vereint. Ökonomisch bedeutsam: Deutsche Unternehmen bauten Lieferketten nach Mittelosteuropa auf; Arbeitnehmerfreizügigkeit galt in Deutschland allerdings erst ab 2011." },
  { id: "ge2-152", cat: "geschichte", topic: "Europäische Einigung", type: "truefalse", emoji: "🚪", level: 3,
    q: "Einen geregelten Austrittsartikel für EU-Staaten gibt es erst seit dem Vertrag von Lissabon.",
    answer: true,
    explain: "Artikel 50 EU-Vertrag kam mit dem Lissabon-Vertrag (in Kraft seit 1. Dezember 2009). Großbritannien war 2017 das erste Land, das ihn auslöste." },
  { id: "ge2-153", cat: "geschichte", topic: "Europäische Einigung", type: "order", emoji: "⏳", level: 2,
    q: "Sortiere die Meilensteine der europäischen Integration.",
    items: ["Montanunion (1951)", "Römische Verträge (1957)", "Vertrag von Maastricht (1992)", "Euro-Bargeld (2002)", "Osterweiterung (2004)"],
    explain: "Vom Sechser-Club für Kohle und Stahl zur Union mit heute 27 Mitgliedern und gemeinsamer Währung." },

  // ── Dekolonisation & Bürgerrechte ──
  { id: "ge2-154", cat: "geschichte", topic: "Dekolonisation", type: "quiz", emoji: "🧂", level: 2,
    q: "Mit welcher Aktion protestierte Mahatma Gandhi 1930 gegen die britische Kolonialherrschaft?",
    options: ["Einem Hungerstreik im Gefängnis von Delhi", "Einem Boykott britischer Eisenbahnen", "Der Besetzung des Hafens von Bombay", "Dem Salzmarsch zum Meer"], answer: 3,
    explain: "Gandhi marschierte rund 385 km zum Meer und gewann dort selbst Salz – ein Bruch des britischen Salzmonopols. Zehntausende wurden verhaftet. Sein gewaltfreier Widerstand inspirierte später Martin Luther King und Nelson Mandela." },
  { id: "ge2-155", cat: "geschichte", topic: "Dekolonisation", type: "event", emoji: "🇮🇳", level: 1, year: "1947",
    title: "Indien wird unabhängig – und geteilt",
    text: "Am 15. August 1947 endet die britische Herrschaft. Britisch-Indien wird in das mehrheitlich hinduistische Indien und das muslimische Pakistan geteilt.",
    more: "Die Teilung löste eine der größten Fluchtbewegungen der Geschichte aus: rund 15 Mio. Menschen, bis zu eine Million Tote bei Gewaltausbrüchen. Gandhi wurde im Januar 1948 von einem hindu-nationalistischen Fanatiker erschossen. Der Kaschmir-Konflikt schwelt bis heute." },
  { id: "ge2-156", cat: "geschichte", topic: "Dekolonisation", type: "event", emoji: "🌍", level: 2, year: "1960",
    title: "Das „Afrikanische Jahr“",
    text: "1960 werden 17 afrikanische Staaten unabhängig, darunter Nigeria, Kongo und fast alle französischen Kolonien südlich der Sahara.",
    more: "Die Kolonialmächte waren durch den Zweiten Weltkrieg geschwächt, die UN-Charta betonte das Selbstbestimmungsrecht, und USA wie UdSSR waren gegen die alten Kolonialreiche. Viele junge Staaten wurden jedoch zum Schauplatz des Kalten Krieges (Kongokrise 1960–65)." },
  { id: "ge2-157", cat: "geschichte", topic: "Dekolonisation", type: "event", emoji: "🚢", level: 3, year: "1956",
    title: "Suezkrise: Das Ende alter Weltmächte",
    text: "Ägyptens Präsident Nasser verstaatlicht den Suezkanal. Großbritannien, Frankreich und Israel greifen an – doch die USA und die Sowjetunion zwingen sie gemeinsam zum Rückzug.",
    more: "Die Demütigung zeigte, dass London und Paris keine Weltmächte mehr waren, die gegen Washington handeln konnten. Frankreich zog daraus den Schluss, auf Europa (Römische Verträge 1957) und eigene Atomwaffen zu setzen." },
  { id: "ge2-158", cat: "geschichte", topic: "Dekolonisation", type: "truefalse", emoji: "🇩🇿", level: 2,
    q: "Algerien wurde 1962 nach einem langen Krieg gegen Frankreich unabhängig.",
    answer: true,
    explain: "Der Algerienkrieg (1954–1962) war besonders brutal, auch durch Folter. Er stürzte Frankreich 1958 in eine Staatskrise, brachte de Gaulle zurück an die Macht und führte zur Fünften Republik." },
  { id: "ge2-159", cat: "geschichte", topic: "Dekolonisation", type: "event", emoji: "✊🏿", level: 1, year: "1990",
    title: "Nelson Mandela kommt frei",
    text: "Am 11. Februar 1990 verlässt Nelson Mandela nach 27 Jahren Haft das Gefängnis. Vier Jahre später wird er in den ersten freien Wahlen Südafrikas zum Präsidenten gewählt.",
    more: "Die Apartheid – Rassentrennung per Gesetz seit 1948 – zerfiel unter innerem Widerstand und internationalen Wirtschaftssanktionen. Mandela setzte auf Versöhnung statt Rache (Wahrheits- und Versöhnungskommission). 1993 erhielt er mit F. W. de Klerk den Friedensnobelpreis." },
  { id: "ge2-160", cat: "geschichte", topic: "Bürgerrechte USA", type: "event", emoji: "🎙️", level: 1, year: "1963",
    title: "„I Have a Dream“",
    text: "Am 28. August 1963 spricht Martin Luther King vor rund 250.000 Menschen beim Marsch auf Washington. Er fordert gleiche Rechte für Schwarze Amerikaner.",
    more: "Ergebnis der Bewegung: Civil Rights Act 1964 (Verbot der Rassentrennung) und Voting Rights Act 1965. King erhielt 1964 als damals jüngster Preisträger den Friedensnobelpreis. Am 4. April 1968 wurde er in Memphis ermordet." },
  { id: "ge2-161", cat: "geschichte", topic: "Bürgerrechte USA", type: "quiz", emoji: "🚌", level: 2,
    q: "Was löste Rosa Parks 1955 in Montgomery aus, als sie ihren Sitzplatz im Bus nicht räumte?",
    options: ["Einen über einjährigen Busboykott", "Den Marsch auf Washington", "Die Gründung der Black Panthers", "Ein Urteil gegen die Schulrassentrennung"], answer: 0,
    explain: "Der Boykott dauerte 381 Tage und machte den jungen Pfarrer Martin Luther King landesweit bekannt. 1956 erklärte der Supreme Court die Rassentrennung in Bussen für verfassungswidrig." },

  // ── Nahost ──
  { id: "ge2-162", cat: "geschichte", topic: "Nahost-Konflikt", type: "event", emoji: "📨", level: 3, year: "1917",
    title: "Balfour-Deklaration",
    text: "Der britische Außenminister Arthur Balfour sagt der zionistischen Bewegung eine „nationale Heimstätte für das jüdische Volk“ in Palästina zu – ohne die Rechte der arabischen Bevölkerung zu beeinträchtigen.",
    more: "Ein Grundwiderspruch: Gleichzeitig hatte Großbritannien Arabern Unabhängigkeit in Aussicht gestellt und mit Frankreich im Sykes-Picot-Abkommen (1916) die Region aufgeteilt. Nach 1918 verwaltete Großbritannien Palästina als Mandatsgebiet." },
  { id: "ge2-163", cat: "geschichte", topic: "Nahost-Konflikt", type: "quiz", emoji: "🇺🇳", level: 2,
    q: "Was beschloss die UN-Vollversammlung im November 1947 für Palästina?",
    options: ["Eine Teilung in einen jüdischen und einen arabischen Staat", "Einen gemeinsamen binationalen Staat", "Die Fortsetzung des britischen Mandats", "Den Anschluss an Jordanien"], answer: 0,
    explain: "Resolution 181 sah zwei Staaten und Jerusalem unter internationaler Verwaltung vor. Die jüdische Seite stimmte zu, die arabischen Staaten lehnten ab." },
  { id: "ge2-164", cat: "geschichte", topic: "Nahost-Konflikt", type: "event", emoji: "🇮🇱", level: 1, year: "1948",
    title: "Gründung des Staates Israel",
    text: "Am 14. Mai 1948 ruft David Ben-Gurion in Tel Aviv den Staat Israel aus. Am nächsten Tag greifen fünf arabische Staaten an. Israel gewinnt den Krieg und vergrößert sein Gebiet.",
    more: "Rund 700.000 Palästinenser flohen oder wurden vertrieben – für sie die „Nakba“ (Katastrophe). Die Flüchtlingsfrage ist bis heute ein Kern des Konflikts. Für Jüdinnen und Juden war Israel nach dem Holocaust ein sicherer Zufluchtsort." },
  { id: "ge2-165", cat: "geschichte", topic: "Nahost-Konflikt", type: "event", emoji: "⚡", level: 2, year: "1967",
    title: "Sechstagekrieg",
    text: "Im Juni 1967 besiegt Israel in sechs Tagen Ägypten, Jordanien und Syrien. Es erobert den Gazastreifen, das Westjordanland mit Ost-Jerusalem, die Golanhöhen und die Sinai-Halbinsel.",
    more: "Den Sinai gab Israel nach dem Friedensvertrag mit Ägypten (Camp David, 1978/79) zurück. Die Besatzung von Westjordanland und Ostjerusalem und der Siedlungsbau prägen den Konflikt bis heute." },
  { id: "ge2-166", cat: "geschichte", topic: "Nahost-Konflikt", type: "whatif", emoji: "🛢️", level: 3,
    q: "Was folgte aus dem Jom-Kippur-Krieg 1973 für Deutschland?",
    steps: ["Arabische Staaten greifen Israel an", "OPEC-Staaten drosseln Öl, Embargo gegen Israels Unterstützer", "Ölpreis vervierfacht sich binnen Monaten", "Autofreie Sonntage in der Bundesrepublik", "Stagflation: Inflation und Arbeitslosigkeit zugleich"],
    text: "Die erste Ölkrise beendete das Nachkriegswachstum endgültig. Im November und Dezember 1973 galten vier autofreie Sonntage. Langfristig förderte der Schock Energiesparen, Nordseeöl und Atomkraft – und zeigte die Abhängigkeit von Energieimporten, ein Thema, das 2022 zurückkehrte." },
  { id: "ge2-167", cat: "geschichte", topic: "Nahost-Konflikt", type: "event", emoji: "🤝", level: 2, year: "1993",
    title: "Oslo-Abkommen",
    text: "Am 13. September 1993 reichen sich Israels Premier Jitzchak Rabin und PLO-Chef Jassir Arafat vor dem Weißen Haus die Hand. Israel und die PLO erkennen sich gegenseitig an; die Palästinenser erhalten begrenzte Selbstverwaltung.",
    more: "Rabin, Arafat und Schimon Peres erhielten 1994 den Friedensnobelpreis. 1995 wurde Rabin von einem jüdischen Extremisten ermordet. Die Endstatusfragen – Grenzen, Jerusalem, Flüchtlinge, Siedlungen – blieben ungelöst." },

  // ── China ──
  { id: "ge2-168", cat: "geschichte", topic: "China", type: "event", emoji: "🇨🇳", level: 1, year: "1949",
    title: "Mao ruft die Volksrepublik aus",
    text: "Am 1. Oktober 1949 proklamiert Mao Zedong in Peking die Volksrepublik China. Die unterlegenen Nationalisten unter Chiang Kai-shek fliehen nach Taiwan.",
    more: "Daher rührt der bis heute ungelöste Taiwan-Konflikt: Peking betrachtet die Insel als abtrünnige Provinz. Unter Mao folgten Enteignungen, Kampagnen gegen „Klassenfeinde“ und ab 1958 der katastrophale „Große Sprung nach vorn“." },
  { id: "ge2-169", cat: "geschichte", topic: "China", type: "event", emoji: "🌾", level: 3, year: "1958",
    title: "„Großer Sprung nach vorn“",
    text: "Mao will China in wenigen Jahren zur Industriemacht machen: Volkskommunen, Stahl aus Hinterhof-Hochöfen. Die Landwirtschaft bricht zusammen – die größte Hungersnot der Geschichte folgt.",
    more: "Schätzungen der Todesopfer 1959–1961 reichen von rund 15 bis über 40 Millionen. Der Hinterhof-Stahl war größtenteils unbrauchbar. Ein Lehrbeispiel dafür, was passiert, wenn Planvorgaben über Realität und Preissignale gestellt werden." },
  { id: "ge2-170", cat: "geschichte", topic: "China", type: "truefalse", emoji: "📕", level: 2,
    q: "Die Kulturrevolution in China dauerte von 1966 bis 1976.",
    answer: true,
    explain: "Mao mobilisierte die jugendlichen Roten Garden gegen angebliche „bürgerliche“ Elemente – auch, um Rivalen auszuschalten. Lehrer, Intellektuelle und Parteikader wurden gedemütigt, verfolgt, getötet. Sie endete erst mit Maos Tod 1976." },
  { id: "ge2-171", cat: "geschichte", topic: "China", type: "event", emoji: "🐈", level: 1, year: "1978",
    title: "Deng Xiaoping öffnet Chinas Wirtschaft",
    text: "Ab Dezember 1978 setzt Deng auf „Reform und Öffnung“: Bauern dürfen Überschüsse selbst verkaufen, Sonderwirtschaftszonen locken ausländisches Kapital an.",
    more: "Sein Motto: „Egal ob die Katze schwarz oder weiß ist – Hauptsache, sie fängt Mäuse.“ Es folgten Jahrzehnte mit oft rund 10 % Wachstum jährlich; Hunderte Millionen Menschen entkamen der Armut. Politisch blieb das Machtmonopol der KP unangetastet." },
  { id: "ge2-172", cat: "geschichte", topic: "China", type: "quiz", emoji: "🏙️", level: 2,
    q: "Welche Stadt wurde 1980 Chinas erste Sonderwirtschaftszone – und wuchs vom Fischerort zur Millionenmetropole?",
    options: ["Shanghai", "Peking", "Shenzhen", "Wuhan"], answer: 2,
    explain: "Shenzhen grenzt an Hongkong und sollte dessen Kapital und Know-how anziehen. Heute leben dort weit über 10 Mio. Menschen; Firmen wie Huawei, Tencent und BYD haben hier ihren Sitz." },
  { id: "ge2-173", cat: "geschichte", topic: "China", type: "event", emoji: "🚫", level: 1, year: "1989",
    title: "Massaker auf dem Tian’anmen-Platz",
    text: "Wochenlang demonstrieren Studenten in Peking für Reformen und Freiheit. In der Nacht zum 4. Juni 1989 lässt die Führung den Platz durch die Armee räumen; Hunderte bis vermutlich Tausende sterben.",
    more: "Das Bild des „Tank Man“, der sich allein einer Panzerkolonne entgegenstellt, ging um die Welt. In China ist das Thema bis heute zensiert. Lehre der KP: wirtschaftliche Öffnung ja, politische nein – während im selben Jahr in Osteuropa die Regime fielen." },
  { id: "ge2-174", cat: "geschichte", topic: "China", type: "truefalse", emoji: "🌐", level: 2,
    q: "China trat 2001 der Welthandelsorganisation (WTO) bei.",
    answer: true,
    explain: "Der Beitritt im Dezember 2001 machte China zur „Werkbank der Welt“. Deutsche Exporteure, besonders Auto- und Maschinenbauer, profitierten enorm – gleichzeitig wuchsen Abhängigkeiten, die heute unter dem Stichwort „De-Risking“ diskutiert werden." },

  // ── Mauerfall & Einheit ──
  { id: "ge2-175", cat: "geschichte", topic: "Wiedervereinigung", type: "event", emoji: "✂️", level: 3, year: "1989",
    title: "Ungarn öffnet die Grenze",
    text: "Am 19. August 1989 fliehen beim „Paneuropäischen Picknick“ an der österreichisch-ungarischen Grenze Hunderte DDR-Bürger. Am 11. September öffnet Ungarn die Grenze offiziell für DDR-Flüchtlinge.",
    more: "Tausende DDR-Bürger warteten in Ungarn und in der Prager Botschaft der Bundesrepublik. Dort verkündete Außenminister Genscher am 30. September die Ausreise – sein Satz ging im Jubel unter. Der Eiserne Vorhang hatte ein Loch, das die DDR nicht mehr stopfen konnte." },
  { id: "ge2-176", cat: "geschichte", topic: "Wiedervereinigung", type: "event", emoji: "🕯️", level: 2, year: "1989",
    title: "Montagsdemonstration in Leipzig",
    text: "Am 9. Oktober 1989 ziehen rund 70.000 Menschen über den Leipziger Ring: „Wir sind das Volk!“ Trotz bereitstehender Sicherheitskräfte bleibt es friedlich.",
    more: "Das war der Durchbruch der Friedlichen Revolution: Danach wagte das Regime keine Gewalt mehr. Die Demonstrationen begannen nach den Friedensgebeten in der Nikolaikirche. Später wandelte sich der Ruf zu „Wir sind ein Volk!“" },
  { id: "ge2-177", cat: "geschichte", topic: "Wiedervereinigung", type: "event", emoji: "🎉", level: 1, year: "1989",
    title: "9. November: Die Mauer fällt",
    text: "Auf einer Pressekonferenz verkündet SED-Politbüromitglied Günter Schabowski versehentlich die sofortige Reisefreiheit: „Das tritt nach meiner Kenntnis … ist das sofort, unverzüglich.“ Noch in der Nacht öffnen sich die Grenzübergänge.",
    more: "Die Regelung sollte eigentlich erst am nächsten Tag gelten – Schabowski war unzureichend informiert. Am Übergang Bornholmer Straße gab der Offizier Harald Jäger dem Druck der Menge nach. Jeder DDR-Bürger erhielt im Westen 100 DM Begrüßungsgeld." },
  { id: "ge2-178", cat: "geschichte", topic: "Wiedervereinigung", type: "quiz", emoji: "📄", level: 1,
    q: "Wer verkündete am 9. November 1989 auf einer Pressekonferenz die sofortige Reisefreiheit?",
    options: ["Erich Honecker", "Egon Krenz", "Hans Modrow", "Günter Schabowski"], answer: 3,
    explain: "Honecker war bereits im Oktober 1989 durch Egon Krenz ersetzt worden. Schabowski las einen Zettel vor, den er kurz zuvor erhalten hatte – die berühmteste Panne der Weltgeschichte." },
  { id: "ge2-179", cat: "geschichte", topic: "Wiedervereinigung", type: "event", emoji: "💱", level: 2, year: "1990",
    title: "Währungsunion: Die D-Mark kommt in den Osten",
    text: "Am 1. Juli 1990 wird die D-Mark Zahlungsmittel in der DDR. Löhne, Renten und Mieten werden 1:1 umgestellt, Sparguthaben je nach Alter bis zu einem Freibetrag 1:1, darüber 2:1.",
    more: "Politisch wollte man die Abwanderung stoppen: „Kommt die D-Mark, bleiben wir – kommt sie nicht, gehn wir zu ihr.“ Ökonomisch war der Kurs hoch umstritten – Bundesbankpräsident Pöhl warnte vor den Folgen für die Wettbewerbsfähigkeit." },
  { id: "ge2-180", cat: "geschichte", topic: "Wiedervereinigung", type: "whatif", emoji: "🏭", level: 3,
    q: "Was folgte aus der Umstellung der DDR-Löhne 1:1 auf D-Mark?",
    steps: ["DDR-Betriebe zahlen Westlöhne in harter Währung", "Produktivität liegt weit unter West-Niveau", "Ostmärkte brechen weg, Kunden wollen Westware", "Massenentlassungen und Betriebsschließungen", "Hohe Transfers West→Ost, Soli ab 1991"],
    text: "Faktisch wurde die DDR-Wirtschaft über Nacht drastisch aufgewertet und dem Weltmarkt ausgesetzt. Die Industrieproduktion brach ein, die Arbeitslosigkeit stieg rasant. Der Solidaritätszuschlag wurde 1991 eingeführt – zunächst befristet." },
  { id: "ge2-181", cat: "geschichte", topic: "Wiedervereinigung", type: "flashcard", emoji: "🏢", level: 3,
    term: "Treuhandanstalt",
    def: "1990 gegründete Behörde, die rund 8.500 volkseigene Betriebe der DDR privatisieren, sanieren oder abwickeln sollte. Bei ihrer Auflösung Ende 1994 stand statt erhoffter Erlöse ein Milliardendefizit.",
    example: "Für viele Ostdeutsche ist die Treuhand bis heute Symbol für Deindustrialisierung und Kränkung; ihr erster Chef Detlev Rohwedder wurde 1991 ermordet." },
  { id: "ge2-182", cat: "geschichte", topic: "Wiedervereinigung", type: "event", emoji: "🌍", level: 3, year: "1990",
    title: "Zwei-plus-Vier-Vertrag",
    text: "Am 12. September 1990 unterzeichnen beide deutsche Staaten und die vier Siegermächte in Moskau den Vertrag, der Deutschland die volle Souveränität zurückgibt.",
    more: "Er ersetzte faktisch einen Friedensvertrag. Deutschland erkannte die Oder-Neiße-Grenze endgültig an, begrenzte die Bundeswehr auf 370.000 Soldaten und verzichtete auf ABC-Waffen. Die sowjetischen Truppen zogen bis 1994 ab; das vereinte Deutschland blieb in der NATO." },
  { id: "ge2-183", cat: "geschichte", topic: "Wiedervereinigung", type: "event", emoji: "🇩🇪", level: 1, year: "1990",
    title: "3. Oktober: Deutschland ist wiedervereinigt",
    text: "Um Mitternacht tritt die DDR der Bundesrepublik bei. Der 3. Oktober wird Nationalfeiertag – der „Tag der Deutschen Einheit“.",
    more: "Warum der 3. Oktober und nicht der 9. November? Der 9.11. war auch Tag der Novemberpogrome 1938 – als Feiertag ungeeignet. Bundeskanzler Helmut Kohl gilt als „Kanzler der Einheit“." },
  { id: "ge2-184", cat: "geschichte", topic: "Wiedervereinigung", type: "truefalse", emoji: "📘", level: 2,
    q: "Für die Wiedervereinigung wurde eine neue gesamtdeutsche Verfassung ausgearbeitet.",
    answer: false,
    explain: "Die DDR trat nach Artikel 23 GG der Bundesrepublik bei – schnell und ohne Verfassungsneuschöpfung. Der Weg über Artikel 146 GG (neue Verfassung per Volksentscheid) wurde diskutiert, aber verworfen." },
  { id: "ge2-185", cat: "geschichte", topic: "Wiedervereinigung", type: "order", emoji: "⏳", level: 2,
    q: "Sortiere den Weg zur deutschen Einheit.",
    items: ["Ungarn öffnet die Grenze (Sept. 1989)", "Montagsdemo in Leipzig (9. Okt. 1989)", "Mauerfall (9. Nov. 1989)", "Währungsunion (1. Juli 1990)", "Wiedervereinigung (3. Okt. 1990)"],
    explain: "Von der ersten Lücke im Eisernen Vorhang bis zur Einheit vergingen nur 13 Monate." },

  // ── Ende der Sowjetunion ──
  { id: "ge2-186", cat: "geschichte", topic: "Ende der UdSSR", type: "event", emoji: "🔓", level: 1, year: "1985",
    title: "Gorbatschow kommt an die Macht",
    text: "Im März 1985 wird Michail Gorbatschow Generalsekretär der KPdSU. Mit **Glasnost** (Offenheit) und **Perestroika** (Umbau) will er das erstarrte System retten.",
    more: "Die Sowjetwirtschaft litt unter Planwirtschaft, Rüstungslast und niedrigem Ölpreis. Entscheidend für Osteuropa: Gorbatschow gab die Breschnew-Doktrin auf – Moskau würde Reformen in den Bruderstaaten nicht mehr mit Panzern stoppen." },
  { id: "ge2-187", cat: "geschichte", topic: "Ende der UdSSR", type: "event", emoji: "☢️", level: 1, year: "1986",
    title: "Reaktorkatastrophe von Tschernobyl",
    text: "Am 26. April 1986 explodiert Block 4 des Kernkraftwerks Tschernobyl in der Ukraine. Eine radioaktive Wolke zieht über Europa; Moskau informiert zunächst nicht.",
    more: "Erst als in Schweden erhöhte Strahlung gemessen wurde, räumte die Sowjetunion den Unfall ein. Gorbatschow sah darin später einen Wendepunkt für Glasnost. In Deutschland führte Tschernobyl 1986 zur Gründung des Bundesumweltministeriums." },
  { id: "ge2-188", cat: "geschichte", topic: "Ende der UdSSR", type: "event", emoji: "🚩", level: 1, year: "1991",
    title: "Die Sowjetunion löst sich auf",
    text: "Nach einem gescheiterten Putsch von Hardlinern im August 1991 zerfällt die UdSSR. Am 25. Dezember 1991 tritt Gorbatschow zurück; über dem Kreml wird die rote Fahne eingeholt.",
    more: "Boris Jelzin, Präsident Russlands, hatte sich dem Putsch auf einem Panzer stehend entgegengestellt – und wurde damit zum neuen starken Mann. Wladimir Putin nannte den Zerfall 2005 die „größte geopolitische Katastrophe des Jahrhunderts“." },
  { id: "ge2-189", cat: "geschichte", topic: "Ende der UdSSR", type: "quiz", emoji: "🗺️", level: 2,
    q: "Wie viele unabhängige Staaten gingen aus der Sowjetunion hervor?",
    options: ["12", "15", "17", "21"], answer: 1,
    explain: "Die 15 Unionsrepubliken wurden selbstständig – von Russland und der Ukraine über die baltischen Staaten bis Kasachstan. Russland übernahm den Sitz im UN-Sicherheitsrat und die Atomwaffen." },
  { id: "ge2-190", cat: "geschichte", topic: "Ende der UdSSR", type: "truefalse", emoji: "🕊️", level: 2,
    q: "Michail Gorbatschow erhielt 1990 den Friedensnobelpreis.",
    answer: true,
    explain: "Ausgezeichnet für seine Rolle beim friedlichen Ende des Kalten Krieges. In Deutschland wird er als Wegbereiter der Einheit verehrt, in Russland gilt er vielen als Verantwortlicher für Zerfall und Chaos der 1990er." },

  // ── Jugoslawienkriege ──
  { id: "ge2-191", cat: "geschichte", topic: "Jugoslawienkriege", type: "event", emoji: "🧩", level: 3, year: "1991",
    title: "Jugoslawien zerfällt im Krieg",
    text: "Am 25. Juni 1991 erklären Slowenien und Kroatien ihre Unabhängigkeit. Die serbisch dominierte Jugoslawische Volksarmee greift ein – es beginnen die blutigsten Kriege in Europa seit 1945.",
    more: "Nach Titos Tod 1980 hatte Nationalismus den Vielvölkerstaat zerrissen, angeheizt u. a. von Serbiens Präsident Slobodan Milošević. Deutschland erkannte Slowenien und Kroatien früh an (Dezember 1991) – international umstritten. Der Bosnienkrieg (1992–1995) forderte rund 100.000 Tote." },
  { id: "ge2-192", cat: "geschichte", topic: "Jugoslawienkriege", type: "event", emoji: "🕯️", level: 1, year: "1995",
    title: "Völkermord von Srebrenica",
    text: "Im Juli 1995 ermorden bosnisch-serbische Truppen unter General Ratko Mladić in der UN-Schutzzone Srebrenica rund 8.000 bosniakische Männer und Jungen. Niederländische Blauhelme greifen nicht ein.",
    more: "Das schwerste Massenverbrechen in Europa seit dem Zweiten Weltkrieg. Danach griff die NATO mit Luftangriffen ein; im Dezember 1995 beendete das Abkommen von Dayton den Bosnienkrieg. Mladić und Karadžić wurden in Den Haag zu lebenslanger Haft verurteilt." },
  { id: "ge2-193", cat: "geschichte", topic: "Jugoslawienkriege", type: "truefalse", emoji: "✈️", level: 2,
    q: "Der Kosovo-Krieg 1999 war der erste Kampfeinsatz der Bundeswehr.",
    answer: true,
    explain: "Deutsche Tornados flogen im Rahmen der NATO-Luftangriffe gegen Jugoslawien – ohne UN-Mandat. Ausgerechnet eine rot-grüne Regierung (Schröder, Fischer) beschloss ihn. Fischer begründete: „Nie wieder Auschwitz.“" },

  // ── 21. Jahrhundert ──
  { id: "ge2-194", cat: "geschichte", topic: "21. Jahrhundert", type: "event", emoji: "🏢", level: 1, year: "2001",
    title: "Terroranschläge vom 11. September",
    text: "Al-Qaida-Terroristen entführen vier Passagierflugzeuge und steuern zwei davon in die Türme des World Trade Centers, eines ins Pentagon. Fast 3.000 Menschen sterben.",
    more: "Folgen: „Krieg gegen den Terror“, Afghanistan-Einsatz ab Oktober 2001 (die Bundeswehr blieb bis 2021), Irakkrieg 2003, verschärfte Sicherheitsgesetze weltweit. Mehrere Attentäter hatten zuvor in Hamburg gelebt und studiert („Hamburger Zelle“)." },
  { id: "ge2-195", cat: "geschichte", topic: "21. Jahrhundert", type: "quiz", emoji: "🛡️", level: 2,
    q: "Wann rief die NATO zum ersten (und bisher einzigen) Mal den Bündnisfall nach Artikel 5 aus?",
    options: ["Nach den Anschlägen vom 11. September 2001", "Kubakrise 1962", "Golfkrieg 1991", "Kosovo-Krieg 1999"], answer: 0,
    explain: "Ironie der Geschichte: Die Beistandsklausel war für einen sowjetischen Angriff auf Europa gedacht – zum Einsatz kam sie zur Unterstützung der USA. Stand: Mitte 2026 weiterhin der einzige Fall." },
  { id: "ge2-196", cat: "geschichte", topic: "Finanzkrise 2008", type: "event", emoji: "🏦", level: 1, year: "2008",
    title: "Lehman Brothers geht pleite",
    text: "Am 15. September 2008 meldet die US-Investmentbank Lehman Brothers Insolvenz an – die größte Pleite der US-Geschichte. Die Finanzkrise eskaliert zur globalen Krise.",
    more: "Die US-Regierung hatte Lehman bewusst nicht gerettet. Danach vertraute keine Bank mehr der anderen, der Interbankenmarkt fror ein. Staaten retteten anschließend Banken mit Hunderten Milliarden – in Deutschland u. a. Hypo Real Estate und die Commerzbank." },
  { id: "ge2-197", cat: "geschichte", topic: "Finanzkrise 2008", type: "whatif", emoji: "🏚️", level: 2,
    q: "Wie wurde aus faulen US-Hauskrediten eine Weltrezession?",
    steps: ["Immobilienblase: Kredite an zahlungsschwache Käufer", "Kredite werden gebündelt und weltweit verkauft", "Hauspreise fallen, Kredite platzen", "Banken misstrauen einander, Kreditklemme", "Weltweite Rezession 2009"],
    text: "Über Verbriefung landeten US-Subprime-Risiken auch in deutschen Banken, etwa der IKB und Landesbanken. Deutschland stürzte 2009 in die tiefste Rezession der Nachkriegszeit; Kurzarbeit und Konjunkturpakete („Abwrackprämie“) federten den Arbeitsmarkt ab." },
  { id: "ge2-198", cat: "geschichte", topic: "Finanzkrise 2008", type: "truefalse", emoji: "🔐", level: 2,
    q: "Merkel und Finanzminister Steinbrück versprachen im Oktober 2008 öffentlich, dass die Spareinlagen der Deutschen sicher sind.",
    answer: true,
    explain: "Am 5. Oktober 2008 traten sie gemeinsam vor die Kameras. Die Garantie war rechtlich kaum bindend, wirkte aber psychologisch: Ein Ansturm auf die Banken blieb aus. Vertrauen ist im Finanzsystem die wichtigste Währung." },
  { id: "ge2-199", cat: "geschichte", topic: "Eurokrise", type: "event", emoji: "🇬🇷", level: 3, year: "2010",
    title: "Griechenland braucht Hilfe – die Eurokrise beginnt",
    text: "Ende 2009 wird klar, dass Griechenlands Defizit viel höher ist als gemeldet. Im Mai 2010 erhält das Land das erste Hilfspaket von Euro-Staaten und IWF; Irland, Portugal, Spanien und Zypern folgen später.",
    more: "Problem der Währungsunion: gemeinsame Geldpolitik, aber getrennte Haushalts- und Wirtschaftspolitik. Als Antwort entstanden Rettungsschirme (EFSF, 2012 der dauerhafte ESM), die Bankenunion und strengere Fiskalregeln. Die Hilfen waren an harte Sparauflagen geknüpft." },
  { id: "ge2-200", cat: "geschichte", topic: "Eurokrise", type: "quiz", emoji: "🎯", level: 2,
    q: "Wer sagte im Juli 2012, die EZB werde „alles Notwendige“ tun, um den Euro zu erhalten („whatever it takes“)?",
    options: ["Christine Lagarde", "Mario Draghi", "Jean-Claude Trichet", "Jens Weidmann"], answer: 1,
    explain: "Draghis Satz am 26. Juli 2012 in London beruhigte die Märkte fast sofort – die Zinsen für Spanien und Italien sanken deutlich. Das angekündigte Anleihekaufprogramm (OMT) musste nie eingesetzt werden. Die Macht der Worte einer Notenbank." },
  { id: "ge2-201", cat: "geschichte", topic: "Eurokrise", type: "truefalse", emoji: "🚪", level: 1,
    q: "Griechenland verließ 2015 die Eurozone.",
    answer: false,
    explain: "Im Juli 2015 lehnten die Griechen in einem Referendum die Sparauflagen ab – doch die Regierung Tsipras akzeptierte kurz darauf ein drittes Hilfspaket. Der „Grexit“ blieb aus; Griechenland nutzt bis heute den Euro." },
  { id: "ge2-202", cat: "geschichte", topic: "21. Jahrhundert", type: "event", emoji: "🌹", level: 1, year: "2011",
    title: "Arabischer Frühling",
    text: "Die Selbstverbrennung des tunesischen Gemüsehändlers Mohamed Bouazizi im Dezember 2010 löst Proteste in der arabischen Welt aus. 2011 stürzen die Machthaber in Tunesien, Ägypten, Libyen und Jemen.",
    more: "Die Bilanz ist ernüchternd: Nur Tunesien wurde vorübergehend Demokratie. In Ägypten übernahm 2013 wieder das Militär, Libyen, Jemen und Syrien versanken in Bürgerkriegen. Der Syrienkrieg wurde zur Hauptursache der Fluchtbewegung nach Europa 2015." },
  { id: "ge2-203", cat: "geschichte", topic: "21. Jahrhundert", type: "event", emoji: "🚶", level: 1, year: "2015",
    title: "„Wir schaffen das“: Die Flüchtlingskrise",
    text: "2015 kommen rund 890.000 Schutzsuchende nach Deutschland, viele aus Syrien, Afghanistan und dem Irak. Am 31. August sagt Kanzlerin Merkel: „Wir schaffen das.“",
    more: "Anfang September 2015 entschied Merkel, in Ungarn festsitzende Flüchtlinge einreisen zu lassen. Die Krise spaltete die Gesellschaft und die EU, stärkte die AfD und führte 2016 zum EU-Türkei-Abkommen. Das Dublin-System, nach dem das Ersteinreiseland zuständig ist, war faktisch zusammengebrochen." },
  { id: "ge2-204", cat: "geschichte", topic: "21. Jahrhundert", type: "event", emoji: "🇬🇧", level: 1, year: "2016",
    title: "Brexit-Referendum",
    text: "Am 23. Juni 2016 stimmen 51,9 % der Briten für den Austritt aus der EU. Nach jahrelangen Verhandlungen verlässt das Vereinigte Königreich die EU am 31. Januar 2020.",
    more: "Premier David Cameron hatte das Referendum angesetzt, um die Euroskeptiker in seiner Partei zu befrieden – und trat nach der Niederlage zurück. Knackpunkt der Verhandlungen war die Grenze zwischen Irland und Nordirland. Der Binnenmarktaustritt wurde Ende 2020 wirksam." },
  { id: "ge2-205", cat: "geschichte", topic: "21. Jahrhundert", type: "truefalse", emoji: "⏱️", level: 1,
    q: "Großbritannien schied wenige Wochen nach dem Referendum 2016 aus der EU aus.",
    answer: false,
    explain: "Der Austritt erfolgte erst am 31. Januar 2020, die Übergangsphase im Binnenmarkt endete am 31. Dezember 2020. Dazwischen lagen drei Premierminister (Cameron, May, Johnson) und mehrere verschobene Austrittstermine." },
  { id: "ge2-206", cat: "geschichte", topic: "21. Jahrhundert", type: "event", emoji: "🦠", level: 1, year: "2020",
    title: "Die Corona-Pandemie",
    text: "Am 11. März 2020 erklärt die WHO Covid-19 zur Pandemie. Weltweit folgen Lockdowns, Schulschließungen und Grenzkontrollen. Ende 2020 werden die ersten Impfstoffe zugelassen – einer davon von BioNTech aus Mainz.",
    more: "Ökonomisch einer der schärfsten Einbrüche seit dem Zweiten Weltkrieg. In Deutschland waren im April 2020 rund 6 Mio. Menschen in Kurzarbeit. Staaten und Notenbanken stemmten sich mit Billionen gegen die Krise – Lehre aus 1929 und 2008. Danach: Lieferkettenprobleme und steigende Inflation." },
  { id: "ge2-207", cat: "geschichte", topic: "21. Jahrhundert", type: "event", emoji: "🇺🇦", level: 1, year: "2022",
    title: "Russlands Großangriff auf die Ukraine",
    text: "Am 24. Februar 2022 greift Russland die gesamte Ukraine an. Der Krieg hatte bereits 2014 mit der Annexion der Krim und Kämpfen im Donbass begonnen.",
    more: "Drei Tage später rief Kanzler Olaf Scholz im Bundestag eine „Zeitenwende“ aus. Deutschland musste sich binnen Monaten von russischem Gas lösen; die Energiepreise und die Inflation schossen 2022 in die Höhe. Finnland (2023) und Schweden (2024) traten der NATO bei." },
  { id: "ge2-208", cat: "geschichte", topic: "21. Jahrhundert", type: "quiz", emoji: "🛡️", level: 2,
    q: "Wie groß war das „Sondervermögen“ für die Bundeswehr, das Scholz im Februar 2022 ankündigte?",
    options: ["50 Mrd. Euro", "100 Mrd. Euro", "200 Mrd. Euro", "500 Mrd. Euro"], answer: 1,
    explain: "Das Sondervermögen wurde im Grundgesetz verankert, damit es nicht unter die Schuldenbremse fällt. 2025 lockerte der Bundestag die Schuldenbremse für Verteidigungsausgaben zusätzlich und schuf ein Sondervermögen für Infrastruktur." },
  { id: "ge2-209", cat: "geschichte", topic: "21. Jahrhundert", type: "order", emoji: "⏳", level: 1,
    q: "Sortiere die Krisen des 21. Jahrhunderts.",
    items: ["Anschläge vom 11. September (2001)", "Lehman-Pleite (2008)", "Annexion der Krim (2014)", "Brexit-Referendum (2016)", "Russischer Großangriff auf die Ukraine (2022)"],
    explain: "Terror, Finanzkrise, Rückkehr der Geopolitik: Das 21. Jahrhundert ist geprägt von Schocks, die Sicherheits-, Wirtschafts- und Europapolitik gleichermaßen verändert haben." },

  // ── Persönlichkeiten ──
  { id: "ge2-210", cat: "geschichte", topic: "Persönlichkeiten", type: "truefalse", emoji: "☝️", level: 2,
    q: "Konrad Adenauer wurde 1949 mit nur einer Stimme Mehrheit zum Kanzler gewählt – seiner eigenen.",
    answer: true,
    explain: "Er erhielt am 15. September 1949 exakt die erforderlichen 202 Stimmen. Auf die Frage, ob er sich selbst gewählt habe: „Selbstverständlich, alles andere wäre mir als Heuchelei erschienen.“ Er regierte dann 14 Jahre, bis 1963 – mit 87." },
  { id: "ge2-211", cat: "geschichte", topic: "Persönlichkeiten", type: "event", emoji: "🏠", level: 3, year: "1955",
    title: "Adenauer holt die letzten Kriegsgefangenen heim",
    text: "Im September 1955 reist Adenauer nach Moskau. Im Gegenzug für die Aufnahme diplomatischer Beziehungen lässt die Sowjetunion die letzten rund 10.000 deutschen Kriegsgefangenen frei.",
    more: "Die „Heimkehr der Zehntausend“ im Lager Friedland machte Adenauer populär wie nie – bei der Bundestagswahl 1957 holte die Union als einzige Partei in der Geschichte der Bundesrepublik die absolute Mehrheit." },
  { id: "ge2-212", cat: "geschichte", topic: "Persönlichkeiten", type: "quiz", emoji: "⏱️", level: 2,
    q: "Wer war am längsten Bundeskanzler der Bundesrepublik?",
    options: ["Helmut Kohl", "Konrad Adenauer", "Angela Merkel", "Helmut Schmidt"], answer: 0,
    explain: "Kohl regierte von 1982 bis 1998 rund 16 Jahre – einige Tage länger als Angela Merkel (2005–2021). Adenauer kam auf 14 Jahre." },
  { id: "ge2-213", cat: "geschichte", topic: "Persönlichkeiten", type: "quiz", emoji: "🎩", level: 1,
    q: "Für welchen Nobelpreis wurde Winston Churchill 1953 ausgezeichnet?",
    options: ["Literatur", "Frieden", "Wirtschaft", "Medizin"], answer: 0,
    explain: "Für seine historischen und biografischen Werke, u. a. seine Geschichte des Zweiten Weltkriegs – und für seine Redekunst. Den Wirtschaftsnobelpreis gibt es erst seit 1969." },
  { id: "ge2-214", cat: "geschichte", topic: "Persönlichkeiten", type: "quiz", emoji: "🗳️", level: 1,
    q: "Welcher US-Präsident wurde als einziger viermal gewählt?",
    options: ["Abraham Lincoln", "Woodrow Wilson", "Franklin D. Roosevelt", "Dwight D. Eisenhower"], answer: 2,
    explain: "Roosevelt gewann 1932, 1936, 1940 und 1944 und starb im April 1945 im Amt. Danach begrenzte der 22. Verfassungszusatz (1951) die Amtszeit auf zwei Wahlperioden." },
);
